const LISTE_ALIMENTATIONS_REDRESSEUR = ["Simple (1 alimentation)", "Double (2 alimentations)"];
function redresseurDoubleAlim(eq) { return /^Double/.test(eq?.identification?.alimentationsAmont || ""); }
