    seuils.filter((x) => !String(x.label || "").trim() && ["reglage", "temporisation"].some((k) => String((x.fields || {})[k] || "").trim())).forEach(() => push("parametrage_relais", "seuil sans fonction de protection choisie (non imprimé dans le rapport)"));
