function champsPieceCatalogueUsure(p) {
  const kinds = p.c === "V" ? ["ventil"] : p.c === "AC" ? ["ac"] : ["dc", "cartes"];
  const hit = p.r ? pieceCatalogueParReference(p.r, kinds) : null;
  if (hit) return { marque: hit.marque || p.m || "", modele: hit.modele || p.r, description: hit.description || p.d || "" };
  return { marque: p.m || "", modele: p.r || "", description: p.d || "" };
}
function PropositionsPiecesUsure({ eq, categories, existants = {}, onAjouter, allSites = [] }) {
  const [catalogue, setCatalogue] = useState(null);
  const [ouvert, setOuvert] = useState(true);
  const [choix, setChoix] = useState(0);
  const [variante, setVariante] = useState(0);
  useEffect(() => {
    let actif = true;
    import("./catalogueUsureConversion.js").then((m) => { if (actif) setCatalogue(m.default || m); }).catch(() => {});
    return () => { actif = false; };
  }, []);
  const ficheAppli = useMemo(() => ficheUsureAppli(eq, allSites), [eq.id, eq.type, eq.identification, allSites]);
  const fiches = useMemo(() => [...(ficheAppli ? [ficheAppli] : []), ...fichesCatalogueUsure(catalogue, eq)], [ficheAppli, catalogue, eq.type, eq.identification]);
  const signature = fiches.map((f) => `${f.mo}|${f.p}`).join(",");
  useEffect(() => { setChoix(0); setVariante(0); }, [signature]);
  if (!fiches.length) return null;
  const fiche = fiches[Math.min(choix, fiches.length - 1)];
  const v = fiche.v[Math.min(variante, fiche.v.length - 1)];
  const pieces = v.p.filter((p) => categories.includes(CAT_USURE_DE_CODE[p.c])).map((p) => ({ p, champs: champsPieceCatalogueUsure(p), cat: CAT_USURE_DE_CODE[p.c] }));
  const dejaLa = (x) => (existants[x.cat] || []).some((m) => {
    const a = normCatalogueUsure(m.modele), b = normCatalogueUsure(x.champs.modele);
    if (a && b) return a === b;
    return !b && normCatalogueUsure(m.description) && normCatalogueUsure(m.description) === normCatalogueUsure(x.champs.description);
  });
  const aAjouter = pieces.filter((x) => !dejaLa(x));
  const fr = (n) => String(n).replace(".", ",");
  const libFiche = (f) => (f.source === "appli" ? "Saisis dans l'appli" : `Historique · ${f.mo}${f.p !== undefined ? ` — ${fr(f.p)} ${f.u || ""}`.trimEnd() : ""}`);
  const puce = (actif) => ({ padding: "4px 10px", borderRadius: 999, fontSize: 11.5, fontWeight: 600, cursor: "pointer", border: `1px solid ${actif ? "#0A5DA8" : "#D8DEE5"}`, background: actif ? "#EEF4FB" : "#fff", color: actif ? "#0A5DA8" : "#5B6B7D" });
  return (
    <Card style={{ marginBottom: 14, borderLeft: "4px solid #0A5DA8" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, flexWrap: "wrap", cursor: "pointer" }} onClick={() => setOuvert((o) => !o)}>
        <div>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#1A1F26" }}>Pièces relevées sur ce modèle</div>
          <div style={{ fontSize: 11.5, color: "#5B6B7D" }}>{fiche.source === "appli"
            ? `Pièces saisies sur ${fiche.n} autre${fiche.n > 1 ? "s" : ""} équipement${fiche.n > 1 ? "s" : ""} du même modèle dans l'appli`
            : `${normCatalogueUsure(fiche.mo).startsWith(normCatalogueUsure(fiche.m)) ? "" : fiche.m + " "}${libFiche(fiche).replace(/^Historique · /, "")} · ${fiche.n} relevé${fiche.n > 1 ? "s" : ""} dans l'historique de maintenance`}</div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }} onClick={(e) => e.stopPropagation()}>
          {ouvert && aAjouter.length > 1 && <button onClick={() => onAjouter(aAjouter)} style={btnGhost(BRAND.blue)}><Plus size={13} /> Tout ajouter ({aAjouter.length})</button>}
          <button onClick={() => setOuvert((o) => !o)} style={{ background: "none", border: "none", color: "#5B6B7D", cursor: "pointer", padding: 4 }} title={ouvert ? "Replier" : "Déplier"}>
            <ChevronDown size={16} style={{ transform: ouvert ? "rotate(0deg)" : "rotate(-90deg)", transition: "transform .15s" }} />
          </button>
        </div>
      </div>
      {ouvert && (
        <div style={{ marginTop: 10 }}>
          {fiches.length > 1 && (
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
              {fiches.map((f, i) => <span key={i} onClick={() => { setChoix(i); setVariante(0); }} style={puce(i === Math.min(choix, fiches.length - 1))}>{f.source !== "appli" && f.m !== fiche.m && i !== choix ? f.m + " " : ""}{libFiche(f)} ({f.n})</span>)}
            </div>
          )}
          {fiche.v.length > 1 && (
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", marginBottom: 8 }}>
              <span style={{ fontSize: 11, color: "#8B96A3" }}>Relevés différents :</span>
              {fiche.v.map((x, i) => <span key={i} onClick={() => setVariante(i)} style={puce(i === Math.min(variante, fiche.v.length - 1))}>{i === 0 ? "Le plus fréquent" : `Variante ${i + 1}`} ({x.n})</span>)}
            </div>
          )}
          {pieces.length === 0 ? (
            <div style={{ fontSize: 12, color: "#8B96A3", fontStyle: "italic" }}>Aucun ventilateur ni condensateur relevé pour ce modèle dans les catégories de cet équipement.</div>
          ) : pieces.map((x, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "7px 0", borderTop: i ? "1px solid #EEF1F4" : "none", flexWrap: "wrap" }}>
              <span style={{ fontSize: 10.5, fontWeight: 700, color: "#5B6B7D", background: "#F4F6F8", borderRadius: 6, padding: "3px 7px", flexShrink: 0, minWidth: 104, textAlign: "center" }}>{LIBELLE_CODE_USURE[x.p.c]}</span>
              <div style={{ flex: "1 1 240px", minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 700, color: "#1A1F26" }}>{[x.champs.marque, x.champs.modele].filter(Boolean).join(" ") || "Référence non relevée"}</div>
                {x.champs.description && <div style={{ fontSize: 11.5, color: "#5B6B7D" }}>{x.champs.description}</div>}
              </div>
              {x.p.nEq ? <span style={{ fontSize: 11, color: "#8B96A3", flexShrink: 0 }}>sur {x.p.nEq} équip.</span> : null}
              {x.p.q ? <span style={{ fontSize: 12, fontWeight: 700, color: "#1A1F26", flexShrink: 0 }}>× {fr(x.p.q)}</span> : null}
              {dejaLa(x)
                ? <span style={{ fontSize: 11.5, color: "#0F8A5F", fontWeight: 600, flexShrink: 0 }}>✓ déjà dans la liste</span>
                : <button onClick={() => onAjouter([x])} style={{ ...btnGhost(BRAND.blue), flexShrink: 0 }}><Plus size={13} /> Ajouter</button>}
            </div>
          ))}
          <div style={{ fontSize: 10.5, color: "#8B96A3", marginTop: 6 }}>{fiche.source === "appli" ? "Pièces saisies par les techniciens sur d'autres équipements du même modèle" : "Proposition issue des plans de maintenance"} : vérifier la référence et la quantité sur place. L'année de mise en service reste à saisir.</div>
        </div>
      )}
    </Card>
  );
}
// Ajoute des pièces proposées aux listes « pièces d'usure » d'un onduleur / redresseur / inverseur (une ligne vide est réutilisée).
function ajouterPiecesUsureUPS(data, choix, categoriesDef) {
  const next = { ...data };
  choix.forEach((x) => {
    const def = categoriesDef.find((c) => c.key === x.cat);
    if (!def) return;
    const liste = [...(next[x.cat] || [])];
    const vide = liste.findIndex((m) => !String(m.description || "").trim() && !String(m.marque || "").trim() && !String(m.modele || "").trim() && !String(m.anneeMiseEnService || "").trim());
    const piece = { ...emptyModeleUsure(def.dureeDefaut), ...x.champs, quantite: x.p.q ? String(x.p.q) : "" };
    if (vide >= 0) liste[vide] = { ...liste[vide], ...x.champs, quantite: piece.quantite };
    else liste.push(piece);
    next[x.cat] = liste;
  });
  return next;
}
function PiecesUsureUPSPanel({ eq, update, itemFicheBatterie, itemsBatterieSup = [], allSites = [] }) {
  const [catalogueOuvert, setCatalogueOuvert] = useState(null); // id du modèle dont le catalogue est ouvert
  const valeurFiche = eq.controles.batterie_id?.batterie_caracteristiques || { fields: {} };
  const setFiche = (v) => update({ ...eq, controles: { ...eq.controles, batterie_id: { ...(eq.controles.batterie_id || {}), batterie_caracteristiques: v } } });
  const data = eq.controles.pieces_usure_ups || {};
  const setCategorie = (catKey, modeles) => update({ ...eq, controles: { ...eq.controles, pieces_usure_ups: { ...data, [catKey]: modeles } } });
  const batterieInfo = eq.controles.batterie_id?.batterie_caracteristiques?.fields || {};
  const quantiteBatteries = (() => {
    const nb = numOf(batterieInfo.nombreBranches), nblocs = numOf(batterieInfo.nombreBlocsParBranche);
    return nb !== null && nblocs !== null ? nb * nblocs : "";
  })();

  return (
    <>
      <PropositionsPiecesUsure eq={eq} allSites={allSites} categories={getCategoriesUsure(eq.type).map((c) => c.key)} existants={data}
        onAjouter={(choix) => update({ ...eq, controles: { ...eq.controles, pieces_usure_ups: ajouterPiecesUsureUPS(data, choix, getCategoriesUsure(eq.type)) } })} />
      {getCategoriesUsure(eq.type).map((cat) => {
        const modeles = data[cat.key] || [];
        const setModele = (id, patch) => setCategorie(cat.key, modeles.map((m) => (m.id === id ? { ...m, ...patch } : m)));
        // Batteries : l'emplacement 0 correspond à la fiche batterie ; on le crée au besoin pour que « Ajouter un modèle » ajoute bien un 2e modèle.
        const addModele = () => setCategorie(cat.key, [...(cat.key === "batteries" && modeles.length === 0 ? [emptyModeleUsure(cat.dureeDefaut)] : []), ...modeles, emptyModeleUsure(cat.dureeDefaut)]);
        const removeModele = (id) => setCategorie(cat.key, modeles.filter((m) => m.id !== id));
        return (
          <Card key={cat.key} style={{ marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
              <SectionTitle>{cat.label}</SectionTitle>
              <button onClick={addModele} style={btnGhost(BRAND.blue)}><Plus size={13} /> Ajouter un modèle</button>
            </div>
            {cat.key === "batteries" && itemFicheBatterie && (
              <div style={{ marginBottom: 6 }}>
                <div style={{ fontSize: 11.5, color: "#8B96A3", marginBottom: 4 }}>Modèle 1 — fiche batterie de l'équipement (reprise par le relevé des tensions, les branches, l'autonomie et le rapport). Un modèle différent s'ajoute avec « Ajouter un modèle ».</div>
                <ControlRow item={itemFicheBatterie} value={valeurFiche} onChange={setFiche} idPrefix={`${eq.id}-fiche-batterie`} />
                {itemsBatterieSup.map((it) => (
                  <div key={it.key} style={{ marginTop: 8 }}>
                    <ControlRow item={it} value={(eq.controles.batterie_id || {})[it.key] || { action: "", etat: "", fields: {} }} idPrefix={`${eq.id}-${it.key}`}
                      onChange={(v) => update({ ...eq, controles: { ...eq.controles, batterie_id: { ...(eq.controles.batterie_id || {}), [it.key]: v } } })} />
                  </div>
                ))}
                {/\d\s*W$/i.test(String(batterieInfo.typeBloc || "").trim()) && !String(batterieInfo.puissanceElement || "").trim() && (
                  <div style={{ fontSize: 11.5, color: "#B5730A", background: "#FDF3E3", borderRadius: 8, padding: "6px 10px", marginTop: 6 }}>
                    La référence « {batterieInfo.typeBloc} » se termine par W : batterie probablement donnée en puissance par élément. Reportez la valeur W/élt, la durée et la tension de fin de décharge de la fiche constructeur (la convention varie selon le fabricant).
                  </div>
                )}
                {(() => {
                  const preco = dureeVieBatterieParCapacite(batterieInfo.capacite);
                  const saisie = numOf(batterieInfo.dureeVie);
                  return (
                    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontSize: 11.5, color: "#5B6B7D", background: "#F4F6F8", borderRadius: 8, padding: "6px 10px", marginTop: 4 }}>
                      <span>Durée de vie préconisée selon la capacité : <b>{preco ? `${preco} ans` : "—"}</b>{batterieInfo.capacite ? ` (${String(batterieInfo.capacite).replace(".", ",")} Ah)` : " (renseigner la capacité)"} — ≤ 12 Ah : 4 ans · ≤ 40 Ah : 5 ans · ≤ 75 Ah : 6 ans · au-delà : 8 ans.</span>
                      {preco && saisie === null && <span style={{ color: "#0A5DA8" }}>Appliquée tant que la durée de vie n'est pas saisie.</span>}
                      {preco && saisie !== null && saisie !== preco && <button type="button" onClick={() => setFiche({ ...valeurFiche, fields: { ...(valeurFiche.fields || {}), dureeVie: String(preco) } })} style={{ ...btnGhost(BRAND.blue), padding: "3px 9px", fontSize: 11.5 }}>Appliquer {preco} ans</button>}
                    </div>
                  );
                })()}
              </div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {modeles.map((m, idx) => {
                if (cat.key === "batteries" && idx === 0 && itemFicheBatterie) return null; // remplacé par la fiche batterie ci-dessus
                const isAutoBatterie = cat.key === "batteries" && idx === 0;
                return (
                  <div key={m.id} style={{ padding: "10px 0", borderBottom: "1px solid #E2E6EB" }}>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                      {isAutoBatterie ? (
                        <>
                          <MiniField label="Marque"><div style={{ ...inputStyle, width: 100, padding: "5px 7px", fontSize: 12, background: "#F4F6F8", color: "#5B6B7D" }}>{batterieInfo.marque || "—"}</div></MiniField>
                          <MiniField label="Modèle (type de bloc)"><div style={{ ...inputStyle, width: 120, padding: "5px 7px", fontSize: 12, background: "#F4F6F8", color: "#5B6B7D" }}>{batterieInfo.typeBloc || "—"}</div></MiniField>
                          <MiniField label="Quantité"><div style={{ ...inputStyle, width: 60, padding: "5px 7px", fontSize: 12, background: "#F4F6F8", color: "#5B6B7D" }}>{quantiteBatteries || "—"}</div></MiniField>
                        </>
                      ) : (
                        <>
                          <MiniInput type="text" multiline label="Description" value={m.description} onChange={(v) => setModele(m.id, { description: v })} width={280} />
                          <MiniInput type="text" label="Marque" value={m.marque} onChange={(v) => setModele(m.id, { marque: v })} width={110} />
                          <MiniInput type="text" label="Modèle" value={m.modele} onChange={(v) => setModele(m.id, { modele: v })} width={150} />
                          <MiniInput label="Quantité" value={m.quantite} onChange={(v) => setModele(m.id, { quantite: v })} width={60} />
                        </>
                      )}
                      <MiniInput label="Année MES" value={m.anneeMiseEnService} onChange={(v) => setModele(m.id, { anneeMiseEnService: v })} width={70} />
                      <MiniInput label="Durée de vie" unit="ans" value={m.dureeVie} onChange={(v) => setModele(m.id, { dureeVie: v })} width={62} />
                      {CATALOGUE_PAR_CATEGORIE_USURE[cat.key] && (
                        <button onClick={() => setCatalogueOuvert(catalogueOuvert === m.id ? null : m.id)} style={btnGhost(BRAND.blue)} title="Rechercher la pièce dans le catalogue (caractéristiques, dimensions, équivalences)">
                          <Search size={13} /> Catalogue
                        </button>
                      )}
                      {!isAutoBatterie && (
                        <BoutonLirePlaque compact libelle="Photo" typeEquipement={eq.type}
                          contexte={`Pièce d'usure « ${cat.label} » d'un équipement « ${eq.type} ». Pour la description, rédiger une description technique courte comme dans un catalogue (ex. capacité µF, tension V, dimensions Ø×H mm, type).`}
                          champs={[
                            { key: "description", label: "Description technique (capacité, tension, dimensions, type…)" },
                            { key: "marque", label: "Marque / fabricant" },
                            { key: "modele", label: "Modèle / référence exacte" },
                            { key: "anneeMiseEnService", label: "Année de fabrication (seulement si un code date est lisible)" },
                          ]}
                          valeursActuelles={m} onAppliquer={(patch) => setModele(m.id, patch)}
                          transformer={(v) => {
                            // Référence lue présente dans le catalogue : marque, référence et description normalisées du catalogue.
                            const kinds = CATALOGUE_PAR_CATEGORIE_USURE[cat.key] ? [CATALOGUE_PAR_CATEGORIE_USURE[cat.key], ...(cat.key === "condensateursContinus" ? ["cartes"] : [])] : ["ac", "dc", "ventil"];
                            const p = pieceCatalogueParReference(v.modele, kinds);
                            return p ? { ...v, marque: p.marque || v.marque, modele: p.modele, description: p.description || v.description } : v;
                          }} />
                      )}
                      {modeles.length > 1 && !(cat.key === "batteries" && idx === 0) && (
                        <button onClick={() => removeModele(m.id)} style={{ background: "none", border: "none", color: "#EF4444", cursor: "pointer", padding: 4 }} title="Retirer">
                          <Trash2 size={15} />
                        </button>
                      )}
                    </div>
                    {catalogueOuvert === m.id && CATALOGUE_PAR_CATEGORIE_USURE[cat.key] && (
                      <CataloguePiecesPicker
                        kind={CATALOGUE_PAR_CATEGORIE_USURE[cat.key]}
                        onFermer={() => setCatalogueOuvert(null)}
                        onChoisir={(choix) => { setModele(m.id, choix); setCatalogueOuvert(null); }}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </Card>
        );
      })}
      <PiecesUsureSyntheseUPS eq={eq} />
    </>
  );
}
function PrevisionRemplacementCarte({ lignes }) {
  const p = previsionRemplacement(lignes);
  if (p.items.length === 0) return null;
  const enTete = ["Pièce", "Échéance", ...p.annees.map(String)];
  return (
    <Card style={{ marginBottom: 14 }}>
      <SectionTitle>Prévision de remplacement des pièces — {p.annees[0]} à {p.annees[3]}</SectionTitle>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
          <thead>
            <tr>{enTete.map((h, i) => <th key={h + i} style={{ background: "#1A1F26", color: "#fff", padding: "7px 10px", textAlign: i === 0 ? "left" : "center", fontWeight: 700, fontSize: 12 }}>{h}{i === 2 && <div style={{ fontSize: 9.5, fontWeight: 400, color: "#C0C6CE" }}>en cours</div>}</th>)}</tr>
          </thead>
          <tbody>
            {p.items.map((l, i) => (
              <tr key={i}>
                <td style={{ padding: "7px 10px", borderBottom: "1px solid #E2E6EB", color: "#3E4A5C" }}>{l.type}</td>
                <td style={{ padding: "7px 10px", borderBottom: "1px solid #E2E6EB", textAlign: "center", fontWeight: 700, color: l.depassee ? "#C0392B" : l.enCours ? "#B5730A" : "#1A1F26" }}>{l.annee}</td>
                {l.etats.map((e, c) => {
                  const couleur = COULEURS_PREVISION[e];
                  return <td key={c} style={{ padding: "7px 10px", borderBottom: "1px solid #fff", textAlign: "center", fontWeight: 700, background: "#" + couleur.fond, color: "#" + couleur.texte, fontSize: e === "ok" ? 12 : 14 }}>{couleur.symbole}</td>;
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {p.items.some((l) => l.enCours || l.depassee) && (
        <div style={{ marginTop: 10, fontSize: 12.5, color: "#3E4A5C" }}>
          {p.items.filter((l) => l.enCours || l.depassee).map((l, i) => (
            <div key={i} style={{ color: l.depassee ? "#C0392B" : "#B5730A", fontWeight: 600 }}>
              • {l.depassee ? `${l.type} : échéance de remplacement dépassée (${l.annee}).` : `${l.type} : remplacement à prévoir cette année (${l.annee}).`}
            </div>
          ))}
        </div>
      )}
      <div style={{ fontSize: 11, color: "#8B96A3", marginTop: 8 }}>Vert (✓) : pièce en bon état prévu, avant son échéance. Orange (●) : année d'échéance — remplacement à faire cette année-là. Rouge (!) : échéance dépassée (années suivantes, si la pièce n'est pas remplacée).</div>
    </Card>
  );
}
function PiecesUsureSyntheseUPS({ eq }) { return <PrevisionRemplacementCarte lignes={calcEcheancesUsureUPS(eq)} />; }
function PiecesUsureSynthese({ eq }) { return <PrevisionRemplacementCarte lignes={calcPiecesUsure(eq)} />; }

function CourantDechargeBranches({ eq, update }) {
  const nb = Math.max(1, Math.round(numOf(eq.controles.batterie_id?.batterie_caracteristiques?.fields?.nombreBranches) || 1));
  const courants = eq.controles.essai_decharge?.courants_branches || {};
  const setBranche = (key, v) => update({ ...eq, controles: { ...eq.controles, essai_decharge: { ...eq.controles.essai_decharge, courants_branches: { ...courants, [key]: v } } } });
  const total = calcCourantDechargeTotal(eq);
  const puissance = calcPuissanceDecharge(eq);
  return (
    <Card style={{ marginBottom: 14 }}>
      <SectionTitle>Courant de décharge par branche</SectionTitle>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginBottom: 10 }}>
        {Array.from({ length: nb }, (_, i) => (
          <MiniInput key={i} label={`Branche ${i + 1}`} unit="A" value={courants[`b${i + 1}`]} onChange={(v) => setBranche(`b${i + 1}`, v)} width={70} />
        ))}
      </div>
      <div style={{ fontSize: 12.5, color: "#5B6B7D" }}>
        Total : <b style={{ color: "#1A1F26" }}>{total ?? "—"} A</b>
        {"  ·  "}Puissance de décharge (calculée) : <b style={{ color: "#1A1F26" }}>{puissance ?? "—"} kW</b>
      </div>
    </Card>
  );
}
// ----- Relais HTA autonomes (sans source auxiliaire), alimentés par leurs capteurs et déclenchant un Mitop / une bobine à faible consommation -----
