    Y.forEach((y, k) => { const y2 = Y[(k + 1) % 3]; ligne(k < 2 ? [[X(80), y], [X(95), y2]] : [[X(80), y], [X(88), y - 22], [X(88), Y[0] - 22], [X(95), Y[0]]]); });
