  ctx.font = `11px ${SCHEMA_POLICE}`; ctx.fillStyle = "#8B96A3"; ctx.textAlign = "left"; ctx.textBaseline = "alphabetic"; ctx.fillText("cuve / masse", 145, y0 + 272);
