                {[...FICHE_MIT520, ...(estTransfoSec(eq) ? FICHE_ISOLEMENT_SEC : FICHE_ISOLEMENT_HUILE)].map((l, i) => <div key={i} style={{ fontSize: 12, color: "#3E4A5C", lineHeight: 1.5 }}>• {l}</div>)}
