// Préconisations dédoublonnées, regroupées par famille, les plus urgentes en premier.
function preconisationsDepuisConstats(constats) {
  const groupes = {};
  constats.forEach((c) => {
    const cle = c.categorie === "etat" ? (c.rang >= 2 ? "etat_defaillant" : "etat_degrade") : c.categorie;
    if (!groupes[cle]) groupes[cle] = { rang: 0, sujets: [] };
    groupes[cle].rang = Math.max(groupes[cle].rang, c.rang);
    groupes[cle].sujets.push(c.sujet);
    if (c.seuilMin) groupes[cle].seuilMin = c.seuilMin;
    if (c.modeBatterie) { groupes[cle].mode = c.modeBatterie; groupes[cle].nbBlocs = c.nbBlocs; }
  });
  // Calibre inadapté : le remplacement « par des fusibles de caractéristiques identiques » serait contradictoire — la préconisation de calibre le remplace.
  if (groupes.fusible_calibre) { delete groupes.fusible; delete groupes.fusible_rechange; }
  delete groupes.corrige; // défauts corrigés lors de la visite : aucune préconisation
  // Courbe sous le seuil bas : pas de seconde préconisation si un remplacement de batterie est déjà demandé.
  if (groupes.batterie_decharge_ponctuel && groupes.batterie_decharge) delete groupes.batterie_decharge_ponctuel;
  if (groupes.batterie_decharge && (groupes.batterie || groupes.batterie_capacite || (groupes.usure && groupes.usure.sujets.some((x) => /batteri/i.test(x))))) {
    const r = groupes.batterie_decharge.rang; delete groupes.batterie_decharge;
    const cible = groupes.batterie || groupes.batterie_capacite; if (cible) cible.rang = Math.max(cible.rang, r);
  }
  // Batteries : blocs défectueux ET fin de vie → une seule préconisation de remplacement, jamais les deux.
  if (groupes.batterie) {
    const usureBat = !!(groupes.usure && groupes.usure.sujets.some((x) => /batteri/i.test(x)));
    groupes.batterie.finDeVie = usureBat;
    if (usureBat) {
      groupes.usure.sujets = groupes.usure.sujets.filter((x) => !/batteri/i.test(x));
      if (!groupes.usure.sujets.length) delete groupes.usure;
    }
  }
  // Un même sujet ne reçoit que la préconisation la plus forte (pas « surveiller » et « remettre en conformité » ensemble).
  if (groupes.etat_degrade) {
    const dejaTraites = new Set(Object.entries(groupes).filter(([k]) => k !== "etat_degrade").flatMap(([, g]) => g.sujets));
    groupes.etat_degrade.sujets = groupes.etat_degrade.sujets.filter((x) => !dejaTraites.has(x));
    if (!groupes.etat_degrade.sujets.length) delete groupes.etat_degrade;
  }
  const recos = Object.keys(groupes)
    .filter((cle) => RECO_PAR_CATEGORIE[cle])
    .sort((a, b) => (groupes[b].rang - groupes[a].rang) || (ORDRE_RECO.indexOf(a) - ORDRE_RECO.indexOf(b)))
    .map((cle) => {
      const g = groupes[cle];
      const sujets = listeFr([...new Set(g.sujets)].map((x) => (cle === "usure" || /^[A-ZÉ0-9]{2}/.test(String(x)) ? x : String(x).charAt(0).toLowerCase() + String(x).slice(1))));
      const t = String(RECO_PAR_CATEGORIE[cle](sujets, g)).trim().replace(/[.\s]+$/, "");
      return finPhrase(g.rang >= 2 ? `${t} — Prioritaire` : t);
    });
  // Courtes et lisibles : au plus 5 préconisations, les plus urgentes d'abord.
  if (recos.length > MAX_PRECONISATIONS) return [...recos.slice(0, MAX_PRECONISATIONS - 1), "Traiter les autres points relevés dans les constats."];
  return recos;
}
// Aperçu des remarques calculées + complément libre du technicien (fiche équipement).
function RemarquesAutomatiques({ eq, update, contexte }) {
  const auto = useMemo(() => { try { return genererRemarquesEquipement(eq, contexte); } catch (e) { return ""; } }, [eq, contexte.rapportDate, contexte.allEquipements, contexte.locaux]); // eslint-disable-line react-hooks/exhaustive-deps
  const modifiees = typeof eq.remarquesModifiees === "string" && eq.remarquesModifiees.trim() !== "";
  const [edition, setEdition] = useState(false);
  const texte = modifiees ? eq.remarquesModifiees : auto;
  const p = remarquesStructurees(texte) ? parserSectionsRemarques(texte.split("\n")) : { constats: [texte].filter(Boolean), preconisations: [], autres: [] };
  const autoAChange = modifiees && eq.remarquesModifieesBase !== undefined && eq.remarquesModifieesBase !== auto;
  const ancienne = ancienneRemarqueEquipement(eq);
  const [voirAncienne, setVoirAncienne] = useState(false);
  const complement = complementEquipement(eq);
  const setComplement = (v) => update({ ...eq, remarquesComplement: v, remarquesAncienne: ancienne });
  const puce = (t, couleur, i) => {
    const m = String(t).match(/^(.*?)\s*—\s*Prioritaire\.?$/i);
    return <div key={i} style={{ display: "flex", gap: 7, fontSize: 13, lineHeight: 1.45, marginBottom: 4 }}><span style={{ color: couleur, fontWeight: 800 }}>•</span><span>{m ? m[1] : t}{m && <b style={{ marginLeft: 6, fontSize: 10.5, color: "#C0392B", letterSpacing: 0.4 }}>PRIORITAIRE</b>}</span></div>;
  };
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, flexWrap: "wrap", marginBottom: 8 }}>
        <label style={{ fontSize: 11, fontWeight: 600, color: "#5B6B7D", letterSpacing: 0.5, textTransform: "uppercase" }}>Remarques et préconisations — {modifiees ? "modifiées à la main" : "automatiques"}</label>
        <span style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {!edition && <button type="button" onClick={() => { if (!modifiees) update({ ...eq, remarquesModifiees: auto, remarquesModifieesBase: auto }); setEdition(true); }} style={{ ...btnGhost(BRAND.blue), padding: "4px 10px", fontSize: 12 }}><PenLine size={12} /> Modifier</button>}
          {edition && <button type="button" onClick={() => { if (String(eq.remarquesModifiees || "").trim() === String(auto).trim()) { const { remarquesModifiees, remarquesModifieesBase, ...reste } = eq; update(reste); } setEdition(false); }} style={{ ...btnGhost("#0F8A5F"), padding: "4px 10px", fontSize: 12 }}>✓ Terminer</button>}
          {modifiees && <button type="button" onClick={() => { const { remarquesModifiees, remarquesModifieesBase, ...reste } = eq; update(reste); setEdition(false); }} style={{ ...btnGhost(), padding: "4px 10px", fontSize: 12 }} title="Abandonne la modification et revient au texte calculé"><RotateCcw size={12} /> Revenir à l'automatique</button>}
        </span>
      </div>
      {modifiees && (
        <div style={{ fontSize: 11.5, borderRadius: 8, padding: "6px 10px", marginBottom: 8, background: autoAChange ? "#FDF3E3" : "#EEF4FB", color: autoAChange ? "#8A5A0A" : "#0A5DA8" }}>
          {autoAChange
            ? "Les contrôles ont changé depuis votre modification : le texte modifié ne se met pas à jour. Vérifiez-le, ou revenez à l'automatique."
            : "Texte modifié à la main : c'est lui qui figure dans le rapport et la synthèse (il ne se met plus à jour automatiquement)."}
        </div>
      )}
      {edition && (
        <TextArea value={eq.remarquesModifiees || ""} onChange={(ev) => update({ ...eq, remarquesModifiees: ev.target.value, remarquesModifieesBase: eq.remarquesModifieesBase ?? auto })} rows={8}
          style={{ width: "100%", minHeight: 180, fontSize: 14, lineHeight: 1.55, boxSizing: "border-box", marginBottom: 6 }} />
      )}
      {edition && <div style={{ fontSize: 11, color: "#8B96A3", marginBottom: 10 }}>Gardez les titres « Constats : » et « Préconisations : » ; une ligne par point (« • » en début de ligne). Ajoutez « — Prioritaire » en fin de ligne pour l'étiquette rouge.</div>}
      {!edition && <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 10, marginBottom: 10 }}>
        <div style={{ background: "#F7F9FB", border: "1px solid #E2E6EB", borderRadius: 10, padding: "10px 12px" }}>
          <div style={{ fontSize: 10.5, fontWeight: 800, color: "#5A6573", letterSpacing: 0.5, marginBottom: 6 }}>CONSTATS</div>
          {p.constats.length ? p.constats.map((t, i) => puce(t, "#8B96A3", i)) : <div style={{ fontSize: 12.5, color: "#8B96A3", fontStyle: "italic" }}>Aucune remarque particulière.</div>}
        </div>
        <div style={{ background: "#F7F9FB", border: "1px solid #E2E6EB", borderRadius: 10, padding: "10px 12px" }}>
          <div style={{ fontSize: 10.5, fontWeight: 800, color: "#0A5DA8", letterSpacing: 0.5, marginBottom: 6 }}>NOS PRÉCONISATIONS</div>
          {p.preconisations.length ? p.preconisations.map((t, i) => puce(t, "#0A5DA8", i)) : <div style={{ fontSize: 12.5, color: "#8B96A3", fontStyle: "italic" }}>Aucune action nécessaire.</div>}
        </div>
      </div>}
      {!modifiees && <div style={{ fontSize: 11, color: "#8B96A3", marginBottom: 10 }}>Calculées à partir des contrôles, des mesures et des pièces d'usure : toujours à jour, reprises telles quelles dans le rapport et la synthèse du site. « Modifier » permet de les retoucher.</div>}
      <Field label="Complément du technicien (facultatif, repris dans le rapport)">
        <TextArea value={complement} onChange={(e) => setComplement(e.target.value)} placeholder="Information à ajouter pour le client (contexte, accès, remarque particulière…)" style={{ minHeight: 80, fontSize: 14, lineHeight: 1.5 }} />
      </Field>
      {ancienne && (
        <div style={{ marginTop: 8, fontSize: 12 }}>
          <button type="button" onClick={() => setVoirAncienne((o) => !o)} style={{ background: "none", border: "none", color: "#5B6B7D", cursor: "pointer", padding: 0, fontSize: 12, textDecoration: "underline" }}>
            {voirAncienne ? "Masquer" : "Voir"} l'ancien texte des remarques (avant automatisation, non repris dans le rapport)
          </button>
          {voirAncienne && (
            <div style={{ marginTop: 6, border: "1px dashed #D8DEE5", borderRadius: 8, padding: 10, background: "#fff" }}>
              <div style={{ whiteSpace: "pre-line", color: "#5B6B7D", fontSize: 12, marginBottom: 8 }}>{ancienne}</div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button type="button" onClick={() => update({ ...eq, remarquesComplement: [complement.trim(), ancienne].filter(Boolean).join("\n"), remarquesAncienne: "" })} style={btnGhost(BRAND.blue)}>Reprendre dans le complément</button>
                <button type="button" onClick={() => update({ ...eq, remarquesComplement: complement, remarquesAncienne: "" })} style={btnGhost("#C0392B")}>Effacer l'ancien texte</button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
// ----- Remarques automatiques -----
// Les constats et préconisations sont recalculés à chaque affichage et à chaque génération du rapport :
// plus de bouton à ne pas oublier. Le technicien peut ajouter un complément libre, repris tel quel.
function estRemarqueGeneree(t) {
  const x = String(t || "").trim();
  return !x || /^(constats?\s*:|aucune anomalie relevée|synthèse générale\s*:)/i.test(x) || x === REMARQUE_STANDARD_EQUIPEMENT.trim() || x === REMARQUE_STANDARD_INSTALLATION.trim();
}
// Complément du technicien : nouveau champ, ou ancienne remarque saisie à la main (texte non généré).
function complementEquipement(eq) {
  if (eq.remarquesComplement !== undefined) return String(eq.remarquesComplement || "");
  return estRemarqueGeneree(eq.remarques) ? "" : String(eq.remarques || "");
}
// Ancien texte généré par le bouton (avant automatisation) : conservé pour consultation, plus repris dans le rapport.
function ancienneRemarqueEquipement(eq) {
  if (eq.remarquesComplement !== undefined) return String(eq.remarquesAncienne || "");
  const t = String(eq.remarques || "").trim();
  return t && estRemarqueGeneree(t) && t !== REMARQUE_STANDARD_EQUIPEMENT.trim() ? t : "";
}
const contexteRemarquesSite = (site) => ({ allEquipements: (site && site.equipements) || [], locaux: (site && site.locaux) || [], rapportDate: (site && site.rapport && site.rapport.date) || "" });
// Texte complet des remarques d'un équipement, tel qu'il figure dans le rapport.
function texteRemarquesRapport(eq, contexte) {
  const rang = RANK_OF[eq.etatFinal] ?? 0;
  const auto = rang < 0 ? (eq.etatFinal === "Non présent" ? "Équipement non présent sur le site." : "La maintenance de cet équipement n'a pas pu être réalisée.") : genererRemarquesEquipement(eq, contexte);
  // Remarques retouchées à la main : elles remplacent le texte automatique (le complément reste ajouté).
  const texte = rang >= 0 && String(eq.remarquesModifiees || "").trim() ? String(eq.remarquesModifiees).trim() : auto;
  const comp = complementEquipement(eq).trim();
  return comp ? `${comp}\n\n${texte}` : texte;
}
// Complément de la synthèse du site (ancienne synthèse saisie à la main reprise si elle n'était pas générée).
function complementSynthese(site) {
  const r = (site && site.rapport) || {};
  if (r.syntheseComplement !== undefined) return String(r.syntheseComplement || "");
  return estRemarqueGeneree(r.syntheseRemarques) ? "" : String(r.syntheseRemarques || "");
}
// État « Fonctionnement de l'installation » : suit le pire état des équipements, sauf choix manuel.
function fonctionnementAuto(site) { return LISTE_ETAT_INSTALLATION[Math.max(0, Math.min(2, worstRank((site.equipements || []).map((e) => e.etatFinal))))]; }
function fonctionnementManuel(site) {
  const r = site.rapport || {};
  if (r.fonctionnementManuel !== undefined) return !!r.fonctionnementManuel;
  return !!r.fonctionnementEtat && r.fonctionnementEtat !== LISTE_ETAT_INSTALLATION[0] && r.fonctionnementEtat !== fonctionnementAuto(site);
}
function etatFonctionnementSite(site) { return fonctionnementManuel(site) ? site.rapport.fonctionnementEtat : fonctionnementAuto(site); }
// Texte structuré « Constats / Préconisations » d'un équipement.
function genererRemarquesEquipement(eq, contexte) {
  const constats = analyserAnomaliesEquipement(eq, contexte);
  // Pièces d'usure remplacées lors de cette maintenance : reprises dans les constats.
  const rempl = contexte && "rapportDate" in contexte ? remplacementsDuRapport(eq, contexte.rapportDate).filter((r) => !(constats.remplacementsCites && constats.remplacementsCites.has(r.id))).map((r) => finPhrase(texteRemplacementClient(r))).filter((t, i, arr) => arr.indexOf(t) === i) : []; // deux lots de ventilateurs remplacés → une seule phrase
  if (!constats.length && rempl.length) return `Constats :\n• Aucune anomalie relevée : contrôles conformes.\n${rempl.map((x) => "• " + x).join("\n")}`;
  if (!constats.length) return "Aucune anomalie relevée : contrôles conformes.";
  const tries = [...constats].sort((a, b) => b.rang - a.rang);
  const recos = preconisationsDepuisConstats(tries);
  return `Constats :\n${[...tries.map((c) => c.phrase), ...rempl].map((x) => "• " + x).join("\n")}${recos.length ? `\n\nPréconisations :\n${recos.map((r) => "• " + r).join("\n")}` : ""}`;
}
// ----- Analyse du texte (pour le rendu Word / aperçu) -----
function remarquesStructurees(texte) { return /^\s*(constats?|préconisations?|synthèse générale)\s*:\s*$/im.test(texte || ""); }
function parserSectionsRemarques(lignes) {
  const out = { constats: [], preconisations: [], autres: [] };
  let courant = "autres";
  (lignes || []).forEach((l) => {
    const t = String(l).trim();
    if (!t) return;
    const h = t.match(/^(constats?|préconisations?|recommandations?)\s*:?\s*$/i);
    if (h) { courant = /^constat/i.test(h[1]) ? "constats" : "preconisations"; return; }
    out[courant].push(t.replace(/^[•\-–*]\s*/, ""));
  });
  return out;
}
function parserSyntheseSite(texte) {
  const blocs = String(texte || "").split(/\n\s*\n/).map((b) => b.split("\n").map((l) => l.trim()).filter(Boolean)).filter((b) => b.length);
  const res = { generale: [], equipements: [] };
  blocs.forEach((lignes) => {
    if (/^synthèse générale\s*:?\s*$/i.test(lignes[0])) { res.generale.push(...lignes.slice(1)); return; }
    if (/^(constats?|préconisations?)\s*:?\s*$/i.test(lignes[0])) {
      // Bloc sans titre (ex. « Préconisations : » séparé par une ligne vide, texte modifié à la main) :
      // rattaché à l'équipement précédent plutôt que traité comme un équipement à part.
      const suite = parserSectionsRemarques(lignes);
      const prec = res.equipements[res.equipements.length - 1];
      if (prec) { prec.constats.push(...suite.constats); prec.preconisations.push(...suite.preconisations); prec.autres.push(...suite.autres); }
      else res.equipements.push({ titre: "", ...suite });
      return;
    }
    res.equipements.push({ titre: lignes[0].replace(/\s*:\s*$/, ""), ...parserSectionsRemarques(lignes.slice(1)) });
  });
  return res;
}
// Version à plat (une ligne, sans puces) d'un texte de remarques — pour tableaux et exports.
function aplatirRemarques(texte) {
  return String(texte || "").replace(/^\s*(constats?|préconisations?|synthèse générale)\s*:\s*$/gim, "").replace(/^\s*[•\-–*]\s*/gm, "").replace(/\s*\n+\s*/g, " ").replace(/\s+/g, " ").trim();
}
// Synthèse structurée du site : paragraphe de synthèse générale, puis un bloc par équipement.
function genererSyntheseSite(site) {
  const equipements = site.equipements || [];
  const n = equipements.length;
  const compteur = { conforme: 0, degrade: 0, defaillant: 0, nonRealise: 0 };
  equipements.forEach((eq) => {
    const r = RANK_OF[eq.etatFinal] ?? 0;
    if (r >= 2) compteur.defaillant++; else if (r === 1) compteur.degrade++; else if (r < 0) compteur.nonRealise++; else compteur.conforme++;
  });
  // État de l'environnement et du fonctionnement de l'installation : il compte dans l'état global du
  // rapport (bandeau), la synthèse doit donc en tenir compte elle aussi.
  const rangInstallation = worstRank([site.rapport && site.rapport.environnementEtat, site.rapport && etatFonctionnementSite(site)].filter(Boolean));
  const phrases = [];
  if (!n) {
    phrases.push("Aucun équipement n'a été renseigné lors de cette intervention.");
  } else {
    phrases.push(`Lors de cette intervention de maintenance préventive${site.nom ? " sur le site " + citer(site.nom) : ""}, ${n > 1 ? n + " équipements ont été contrôlés" : "1 équipement a été contrôlé"}.`);
    if (compteur.conforme === n) {
      phrases.push(n > 1 ? "Tous les équipements sont conformes." : "Cet équipement est conforme.");
    } else if (n === 1) {
      phrases.push(compteur.nonRealise ? "La maintenance de cet équipement n'a pas pu être réalisée." : `Cet équipement est ${compteur.defaillant ? "défaillant" : "dégradé"}.`);
    } else {
      const parts = [];
      if (compteur.conforme) parts.push(compteur.conforme > 1 ? `${compteur.conforme} sont conformes` : "1 est conforme");
      if (compteur.degrade) parts.push(compteur.degrade > 1 ? `${compteur.degrade} sont dégradés` : "1 est dégradé");
      if (compteur.defaillant) parts.push(compteur.defaillant > 1 ? `${compteur.defaillant} sont défaillants` : "1 est défaillant");
      if (compteur.nonRealise) parts.push(compteur.nonRealise > 1 ? `${compteur.nonRealise} n'ont pas pu être contrôlés` : "1 n'a pas pu être contrôlé");
      phrases.push(`Parmi eux, ${listeFr(parts)}.`);
    }
    if (compteur.defaillant) phrases.push("Des défaillances ont été constatées : une remise en conformité rapide est à prévoir sur les équipements concernés (voir le plan d'actions et la fiche de chaque équipement).");
    else if (compteur.degrade) phrases.push("Aucune défaillance n'a été constatée, mais certains équipements présentent une dégradation qu'il convient de surveiller ou de corriger (voir le plan d'actions et la fiche de chaque équipement).");
    else if (rangInstallation >= 2) phrases.push("Les équipements ne présentent pas d'anomalie, mais l'environnement ou le fonctionnement de l'installation présente une défaillance nécessitant une action rapide (voir le rapport ci-dessus).");
    else if (rangInstallation === 1) phrases.push("Les équipements ne présentent pas d'anomalie, mais l'environnement ou le fonctionnement de l'installation présente une dégradation qu'il convient de surveiller ou de corriger (voir le rapport ci-dessus).");
    else if (compteur.nonRealise) phrases.push("Aucune anomalie n'a été relevée sur les équipements contrôlés.");
    else phrases.push("L'installation est en bon état général : aucune anomalie majeure n'a été relevée lors de cette intervention.");
    if (compteur.defaillant || compteur.degrade) phrases.push("La réalisation des actions préconisées sera vérifiée lors de la prochaine maintenance préventive.");
  }
  const prochaine = site.rapport && site.rapport.prochaineMaintenance;
  if (prochaine && /^\d{4}-\d{2}-\d{2}/.test(prochaine)) {
    const [y, m, d] = prochaine.slice(0, 10).split("-");
    phrases.push(`La prochaine maintenance préventive est recommandée avant le ${d}/${m}/${y}${compteur && compteur.defaillant ? ", après remise en conformité des équipements défaillants" : ""}.`);
  }
  const ctx = contexteRemarquesSite(site);
  const blocs = [...equipements]
    .map((e) => ({ e, texte: texteRemarquesRapport(e, ctx) }))
    // Équipements sans remarque : regroupés automatiquement en « conformes » dans le rapport.
    .filter(({ e, texte }) => remarquesStructurees(texte) || complementEquipement(e).trim() || (RANK_OF[e.etatFinal] ?? 0) !== 0)
    .sort((a, b) => (RANK_OF[b.e.etatFinal] ?? 0) - (RANK_OF[a.e.etatFinal] ?? 0))
    .map(({ e, texte }) => {
      const titre = `${e.type}${nomEquipementSite(e, site) ? " (" + nomEquipementSite(e, site) + ")" : ""}`;
      // Pas de ligne vide à l'intérieur d'un bloc : une ligne vide sépare deux équipements.
      if (remarquesStructurees(texte)) return `${titre}\n${texte.trim().replace(/\n\s*\n/g, "\n")}`;
      const lignes = texte.trim().split("\n").map((l) => l.trim().replace(/^[•\-–*]\s*/, "")).filter(Boolean);
      return `${titre}\nConstats :\n${lignes.map((l) => "• " + finPhrase(l)).join("\n")}`;
    });
  const complement = complementSynthese(site).trim();
  return ["Synthèse générale :\n" + phrases.join(" ") + (complement ? "\n" + complement : ""), ...blocs].join("\n\n");
}

// ===== Valeurs habituelles par modèle (historique de maintenance 2024-2025 + saisies de l'appli) =====
