    const logo = await chargerImage(LOGO_DARK);
    const lh = Math.round(H * (format === "24" ? 0.26 : 0.22)), lw = Math.min(largeurTexte, Math.round(lh * (logo.width / logo.height)));
    ctx.drawImage(logo, x, y, lw, lh);
