    let t = taille;
    ctx.font = `${gras ? "bold " : ""}${t}px Arial, sans-serif`;
    while (t > 12 && ctx.measureText(texte).width > largeurTexte) { t -= 1; ctx.font = `${gras ? "bold " : ""}${t}px Arial, sans-serif`; }
    ctx.fillText(texte, x, y);
