// Une intervention est clôturée si le technicien l'a marquée manuellement comme telle, ou si elle
// est signée par le client ET le technicien. Partagée entre l'aperçu des interventions et le
// rappel sur la page d'accueil.
function estInterventionCloturee(iv) { return iv.statut === "Clôturée" || !!(iv.validation && iv.validation.signatureClient && iv.validation.signatureHT); }
function InterventionsOverview({ interventions, sites, onOpen, onCreate, onPlanifier }) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const [planifierOpen, setPlanifierOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [groupeMode, setGroupeMode] = useState("date"); // "date" | "client" | "technicien"

  const filtered = useMemo(() => {
    if (!query.trim()) return interventions;
    const q = query.toLowerCase();
    return interventions.filter((iv) => (iv.numeroRI + " " + iv.client + " " + iv.site + " " + iv.technicien).toLowerCase().includes(q));
  }, [interventions, query]);

  const sorted = useMemo(() => [...filtered].sort((a, b) => new Date(b.date) - new Date(a.date)), [filtered]);

  const estCloturee = estInterventionCloturee;
  const estPlanifiee = (iv) => iv.statut === "Planifiée" && !estCloturee(iv);

  // Interventions clôturées : classées à part, Client ▸ Année ▸ Mois (repliable) ; les autres restent en liste.
  const enCours = useMemo(() => sorted.filter((iv) => !estInterventionCloturee(iv)), [sorted]);
  const cloturees = useMemo(() => sorted.filter((iv) => estInterventionCloturee(iv)), [sorted]);
  const [clotureesOuvert, setClotureesOuvert] = useState(false);
  const groupes = useMemo(() => {
    if (groupeMode === "date") return [];
    const parCle = new Map();
    enCours.forEach((iv) => {
      let key;
      if (groupeMode === "technicien") key = (iv.technicien || "Non assigné").trim() || "Non assigné";
      else key = (iv.client || "Client non renseigné").trim() || "Client non renseigné";
      if (!parCle.has(key)) parCle.set(key, []);
      parCle.get(key).push(iv);
    });
    return Array.from(parCle.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  }, [enCours, groupeMode]);

  const IvRow = ({ iv }) => (
    <div key={iv.id} onClick={() => onOpen(iv.id)} className="iv-row"
      style={{ background: "#FFFFFF", border: "1px solid #D8DEE5", borderRadius: 12, padding: "13px 16px", cursor: "pointer" }}
      onMouseEnter={(e) => (e.currentTarget.style.borderColor = "#9AA5B1")} onMouseLeave={(e) => (e.currentTarget.style.borderColor = "#D8DEE5")}
    >
      <div className="iv-row-meta hide-mobile" style={{ flex: "0 0 100px", fontSize: 11.5, color: "#5B6B7D", fontWeight: 700 }}>{iv.numeroRI}</div>
      <div className="iv-row-main" style={{ flex: "1 1 220px", minWidth: 0 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700, color: "#1A1F26", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", display: "flex", alignItems: "center", gap: 6 }}>
          {groupeMode !== "client" && (iv.client || "Client non renseigné")}
          {estPlanifiee(iv) && <span title="Planifiée, pas encore commencée" style={{ fontSize: 10, color: "#0A5DA8", background: "rgba(10,93,168,0.1)", padding: "2px 6px", borderRadius: 4, fontWeight: 700 }}>PLANIFIÉE</span>}
          {estCloturee(iv) && <span title="Clôturée (signée client + technicien)" style={{ fontSize: 10, color: "#0F8A5F", background: "rgba(15,138,95,0.1)", padding: "2px 6px", borderRadius: 4, fontWeight: 700 }}>CLÔTURÉE</span>}
        </div>
        <div style={{ fontSize: 12, color: "#5B6B7D" }}>{iv.numeroRI} · {iv.site || "—"}{groupeMode === "technicien" ? "" : iv.technicien ? " · " + iv.technicien : ""}</div>
      </div>
      <div className="iv-row-meta" style={{ flex: "0 0 100px", fontSize: 12, color: "#3E4A5C" }}>{iv.date}</div>
      <div className="iv-row-meta" style={{ flex: "0 0 120px" }}><StatusBadge label={iv.conclusion} /></div>
      <ChevronRight size={16} color="#9AA5B1" className="hide-mobile" />
    </div>
  );

  return (
    <div>
      <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap", alignItems: "center" }}>
        <div style={{ flex: "1 1 220px", position: "relative" }}>
          <Search size={15} style={{ position: "absolute", left: 11, top: 10, color: "#8B96A3" }} />
          <TextInput placeholder="Rechercher N° CRI, client, site, technicien…" value={query} onChange={(e) => setQuery(e.target.value)} style={{ paddingLeft: 32 }} />
        </div>
        <Select value={groupeMode} onChange={(e) => setGroupeMode(e.target.value)} style={{ width: 180 }}>
          <option value="date">Trier par date</option>
          <option value="client">Grouper par client</option>
          <option value="technicien">Grouper par technicien</option>
        </Select>
        <button onClick={() => onCreate(null, null)} style={btnGhost("#FFC107")}><Plus size={14} /> Rapport vierge</button>
        <button onClick={() => setPlanifierOpen(true)} style={btnGhost(BRAND.blue)}><Clock size={14} /> Planifier à l'avance</button>
        <button onClick={() => setPickerOpen(true)} style={btnPrimary()}><Plus size={15} /> Pré-remplir depuis un site</button>
      </div>

      {sorted.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 20px", background: "#FFFFFF", border: "1px dashed #D8DEE5", borderRadius: 14 }}>
          <ClipboardList size={28} color="#9AA5B1" style={{ marginBottom: 10 }} />
          <div style={{ fontSize: 14, fontWeight: 600, color: "#3E4A5C", marginBottom: 4 }}>
            {interventions.length === 0 ? "Aucun compte rendu d'intervention" : "Aucun résultat pour cette recherche"}
          </div>
          <div style={{ fontSize: 12.5, color: "#8B96A3" }}>Créez votre premier rapport à transmettre au client.</div>
        </div>
      ) : (
      <>
      {enCours.length === 0 ? null : groupeMode !== "date" ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
          {groupes.map(([cle, ivs]) => (
            <div key={cle}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: "#5B6B7D", marginBottom: 8, textTransform: "uppercase", letterSpacing: 0.4, display: "flex", alignItems: "center", gap: 8 }}>
                {cle} <span style={{ fontWeight: 400, color: "#8B96A3", textTransform: "none" }}>({ivs.length} intervention{ivs.length > 1 ? "s" : ""})</span>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {ivs.map((iv) => <IvRow key={iv.id} iv={iv} />)}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {enCours.map((iv) => <IvRow key={iv.id} iv={iv} />)}
        </div>
      )}
      {cloturees.length > 0 && (
        <div style={{ marginTop: 26 }}>
          <div onClick={() => setClotureesOuvert(!clotureesOuvert)} style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", fontSize: 12.5, fontWeight: 700, color: "#0F8A5F", textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 8, userSelect: "none" }}>
            {clotureesOuvert || query.trim() ? <ChevronDown size={15} /> : <ChevronRight size={15} />}
            Interventions clôturées <span style={{ fontWeight: 400, color: "#8B96A3", textTransform: "none" }}>({cloturees.length}) — classées par client, année et mois</span>
          </div>
          {(clotureesOuvert || query.trim()) && (
            <ArbreClientAnneeMois items={cloturees} getClient={(iv) => iv.client} getDate={(iv) => iv.date} unite="intervention" toutOuvert={!!query.trim()}
              renderItem={(iv) => <IvRow key={iv.id} iv={iv} />} />
          )}
        </div>
      )}
      </>
      )}

      {planifierOpen && (
        <PlanifierInterventionPicker
          sites={sites}
          onCancel={() => setPlanifierOpen(false)}
          onConfirm={(site, equipIds, dateISO, technicien) => onPlanifier(site, equipIds, dateISO, technicien)}
        />
      )}

      {pickerOpen && (
        <InterventionPrefillPicker
          sites={sites}
          onCancel={() => setPickerOpen(false)}
          onConfirm={(site, eq) => { onCreate(site, eq); setPickerOpen(false); }}
        />
      )}
    </div>
  );
}

/* =========================================================================
   Calendrier
   ========================================================================= */
const WEEKDAYS_FR = ["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"];
const MONTHS_FR = ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"];

function isoOf(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; }
function parseIso(s) { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); }
function addDays(d, n) { const r = new Date(d); r.setDate(r.getDate() + n); return r; }
function startOfWeekMon(d) { const r = new Date(d); const day = (r.getDay() + 6) % 7; r.setDate(r.getDate() - day); r.setHours(0, 0, 0, 0); return r; }

// =============================================================================================
// Calendriers abonnables (Apple Calendrier, Outlook, Google…) : un fichier .ics par technicien (et un
// fichier « Tous »), publié dans Firebase Storage sous un dossier secret (calendriers/<clé>/<tech>.ics),
// régénéré automatiquement à chaque modification du planning. Lecture publique de CE fichier seulement
// (règle Storage « allow get » sur calendriers/{cle}/{fichier}) : le lien n'est connu que des abonnés et
// peut être renouvelé à tout moment (nouvelle clé). Sens unique : l'app alimente l'agenda.
const CALENDRIER_FENETRE_PASSE_JOURS = 30; // interventions récentes conservées dans l'agenda
const slugTechnicien = (nom) => String(nom || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "sans-nom";
const urlCalendrier = (cle, slug) => `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o/${encodeURIComponent(`calendriers/${cle}/${slug}.ics`)}?alt=media`;
const icsEchapper = (t) => String(t || "").replace(/\\/g, "\\\\").replace(/;/g, "\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
// Repli des lignes longues (RFC 5545 : 75 octets) — coupe sur des caractères, marge pour l'UTF-8.
function icsPlier(ligne) {
  const out = []; let reste = ligne;
  while (reste.length > 60) { out.push(reste.slice(0, 60)); reste = " " + reste.slice(60); }
  out.push(reste);
  return out.join("\r\n");
}
const icsDate = (iso) => String(iso || "").replace(/-/g, "");
const icsDateHeure = (iso, hhmm) => `${icsDate(iso)}T${String(hhmm).replace(":", "").padEnd(4, "0")}00`;
const lendemain = (iso) => { const d = new Date(`${iso}T12:00:00`); d.setDate(d.getDate() + 1); return d.toISOString().slice(0, 10); };
const lienItineraire = (adresse) => `https://maps.apple.com/?daddr=${encodeURIComponent(adresse)}`;
const lienGoogleMaps = (adresse) => `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(adresse)}`;
function lignesContact(c) {
  if (!c) return [];
  const nom = [c.prenom, c.nom].filter(Boolean).join(" ");
  const l = [];
  if (nom) l.push(`Contact sur site : ${nom}`);
  if (c.portable) l.push(`Portable : ${c.portable}`);
  if (c.fixe) l.push(`Fixe : ${c.fixe}`);
  if (c.email) l.push(`E-mail : ${c.email}`);
  return l;
}
// Récapitulatif des équipements et des pièces d'usure à remplacer (échéance atteinte l'année de l'intervention).
function lignesEquipementsCalendrier(equipements, annee) {
  const l = [];
  (equipements || []).forEach((eq) => {
    const rep = eq.identification?.repere || eq.reference || "";
    l.push(`• ${eq.type || "Équipement"}${rep ? ` — ${rep}` : ""}`);
    let alertes = [];
    try { alertes = alertesUsureEquipement(eq, annee); } catch (e) { alertes = []; }
    alertes.forEach((a) => l.push(`    ↳ À remplacer : ${a.type} (échéance ${a.annee}${a.enRetard ? ", dépassée" : ""})`));
  });
  return l;
}
// Site physique lié à un compte rendu d'intervention (lien direct, sinon client + nom du site).
function siteDeIntervention(iv, sites) {
  const id = iv.linkedSiteId || (iv.equipements || []).map((e) => e.sourceSiteId).find(Boolean);
  if (id) { const s = sites.find((x) => x.id === id); if (s) return s; }
  const n = (x) => String(x || "").trim().toLowerCase();
  return sites.filter((s) => n(s.client) === n(iv.client) && (!n(iv.site) || n(s.nom || s.local) === n(iv.site)))
    .sort((a, b) => String(b.rapport?.date || "").localeCompare(String(a.rapport?.date || "")))[0] || null;
}
// Événements de l'agenda : RMP (sites) et comptes rendus d'intervention, du passé récent à l'avenir.
function evenementsCalendrier(sites, interventions) {
  const limite = new Date(); limite.setDate(limite.getDate() - CALENDRIER_FENETRE_PASSE_JOURS);
  const depuis = limite.toISOString().slice(0, 10);
  const out = [];
  (sites || []).forEach((s) => {
    const r = s.rapport || {};
    if (!r.date || r.date < depuis) return;
    const techniciens = [r.intervenant, ...(r.intervenantsSupplementaires || [])].map((t) => String(t || "").trim()).filter(Boolean);
    const annee = Number(String(r.date).slice(0, 4));
    const siteNom = s.nom || s.local || "Site sans nom";
    out.push({
      uid: `rmp-${s.id}@ht-maintenance`, techniciens, date: r.date, dateFin: r.dateFin || "", heureDebut: r.heureArrivee || "", heureFin: r.heureFin || "",
      titre: `${siteNom}${s.client ? ` — ${s.client}` : ""} · Maintenance préventive`,
      adresse: s.adresse || "",
      description: [
        `Site : ${siteNom}`, s.client && `Client : ${s.client}`, s.adresse && `Adresse : ${s.adresse}`,
        s.adresse && `Itinéraire (Plans) : ${lienItineraire(s.adresse)}`, s.adresse && `Itinéraire (Google Maps) : ${lienGoogleMaps(s.adresse)}`,
        ...lignesContact(s.contactSite),
        techniciens.length && `Technicien(s) : ${techniciens.join(", ")}`,
        "", `Équipements (${(s.equipements || []).length}) :`, ...lignesEquipementsCalendrier(s.equipements, annee),
      ].filter((x) => x !== false && x !== null && x !== undefined && x !== 0).join("\n"),
    });
  });
  (interventions || []).forEach((iv) => {
    if (!iv.date || iv.date < depuis) return;
    const s = siteDeIntervention(iv, sites || []);
    const techniciens = [iv.technicien, ...(iv.techniciensSupplementaires || [])].map((t) => String(t || "").trim()).filter(Boolean);
    const annee = Number(String(iv.date).slice(0, 4));
    const siteNom = iv.site || (s && (s.nom || s.local)) || "Site non renseigné";
    const adresse = (s && s.adresse) || "";
    // Équipements du RI, enrichis de l'équipement suivi (pièces d'usure) quand le lien existe.
    const equipements = (iv.equipements || []).map((e) => {
      const suivi = e.sourceEquipementId && (sites || []).flatMap((x) => x.equipements || []).find((x) => x.id === e.sourceEquipementId);
      return suivi ? { ...suivi, reference: e.reference } : { type: e.type, reference: e.reference, identification: { repere: e.reference } };
    });
    out.push({
      uid: `ri-${iv.id}@ht-maintenance`, techniciens, date: iv.date, dateFin: iv.dateFin || "", heureDebut: iv.heureDebut || "", heureFin: iv.heureFin || "",
      titre: `${siteNom}${iv.client ? ` — ${iv.client}` : ""} · Intervention ${iv.numeroRI || ""}`.trim(),
      adresse,
      description: [
        `Site : ${siteNom}`, iv.client && `Client : ${iv.client}`, iv.numeroRI && `Rapport : ${iv.numeroRI}${iv.statut ? ` (${iv.statut})` : ""}`,
        adresse && `Adresse : ${adresse}`, adresse && `Itinéraire (Plans) : ${lienItineraire(adresse)}`, adresse && `Itinéraire (Google Maps) : ${lienGoogleMaps(adresse)}`,
        ...lignesContact(s && s.contactSite), !(s && s.contactSite && s.contactSite.email) && iv.emailClient && `E-mail : ${iv.emailClient}`,
        techniciens.length && `Technicien(s) : ${techniciens.join(", ")}`,
        "", `Équipements (${equipements.length}) :`, ...lignesEquipementsCalendrier(equipements, annee),
      ].filter((x) => x !== false && x !== null && x !== undefined && x !== 0).join("\n"),
    });
  });
  return out.sort((a, b) => String(a.date).localeCompare(String(b.date)));
}
function genererIcs(nomCalendrier, evenements) {
  const maintenant = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
  const l = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//HT Maintenance//Planning//FR", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
    `X-WR-CALNAME:${icsEchapper(nomCalendrier)}`, "X-WR-TIMEZONE:Europe/Paris", "REFRESH-INTERVAL;VALUE=DURATION:PT1H", "X-PUBLISHED-TTL:PT1H"];
  evenements.forEach((e) => {
    const avecHeure = /^\d{1,2}:\d{2}$/.test(e.heureDebut);
    const fin = e.dateFin && e.dateFin > e.date ? e.dateFin : e.date;
    l.push("BEGIN:VEVENT", `UID:${e.uid}`, `DTSTAMP:${maintenant}`);
    if (avecHeure) {
      l.push(`DTSTART:${icsDateHeure(e.date, e.heureDebut)}`);
      const hf = /^\d{1,2}:\d{2}$/.test(e.heureFin) ? e.heureFin : null;
      l.push(`DTEND:${hf ? icsDateHeure(fin, hf) : icsDateHeure(e.date, `${String(Math.min(23, Number(e.heureDebut.split(":")[0]) + 4)).padStart(2, "0")}:${e.heureDebut.split(":")[1]}`)}`);
    } else {
      l.push(`DTSTART;VALUE=DATE:${icsDate(e.date)}`, `DTEND;VALUE=DATE:${icsDate(lendemain(fin))}`);
    }
    l.push(`SUMMARY:${icsEchapper(e.titre)}`);
    if (e.adresse) l.push(`LOCATION:${icsEchapper(e.adresse)}`);
    l.push(`DESCRIPTION:${icsEchapper(e.description)}`, "END:VEVENT");
  });
  l.push("END:VCALENDAR");
  return l.map(icsPlier).join("\r\n") + "\r\n";
}
// Fichiers à publier : un par technicien + « tous ».
function fichiersCalendrier(sites, interventions, techniciensConnus = []) {
  const evs = evenementsCalendrier(sites, interventions);
  const noms = new Set([...techniciensConnus, ...evs.flatMap((e) => e.techniciens)].map((t) => String(t || "").trim()).filter(Boolean));
  const out = { tous: { nom: "Tous les techniciens", ics: genererIcs("HT Maintenance — Planning", evs) } };
  noms.forEach((t) => {
    const slug = slugTechnicien(t);
    const n = slugTechnicien(t);
    out[slug] = { nom: t, ics: genererIcs(`HT Maintenance — ${t}`, evs.filter((e) => e.techniciens.some((x) => slugTechnicien(x) === n))) };
  });
  return out;
}
// Clé secrète des liens (document app-data/calendrier) : créée au premier besoin, renouvelable.
const nouvelleCleCalendrier = () => Array.from(crypto.getRandomValues(new Uint8Array(18))).map((b) => b.toString(16).padStart(2, "0")).join("");
let cleCalendrierCache = null;
async function cleCalendrier(idToken, user, { renouveler = false, creer = true } = {}) {
  if (cleCalendrierCache && !renouveler) return cleCalendrierCache;
  if (!renouveler) {
    const brut = await lireJsonDistant("app-data/calendrier", idToken);
    const cfg = brut ? JSON.parse(brut) : null;
    if (cfg && cfg.cle) { cleCalendrierCache = cfg.cle; return cfg.cle; }
    if (!creer) return null; // aucun abonnement créé : rien à publier automatiquement
  }
  const cle = nouvelleCleCalendrier();
  await firestoreRestSet("app-data/calendrier", JSON.stringify({ cle, creeLe: new Date().toISOString() }), Date.now(), user, idToken);
  cleCalendrierCache = cle;
  return cle;
}
const derniersIcsPublies = {}; // `${cle}/${slug}` → contenu publié (évite les envois inutiles)
// Le DTSTAMP change à chaque génération : comparaison sans cette ligne.
const sansDtstamp = (ics) => ics.replace(/\r\nDTSTAMP:[^\r]*/g, "");
async function publierCalendriers(sites, interventions, techniciensConnus, user, { creer = true } = {}) {
  if (!user || (typeof navigator !== "undefined" && navigator.onLine === false)) return null;
  const idToken = await user.getIdToken();
  const cle = await cleCalendrier(idToken, user.email, { creer });
  if (!cle) return null;
  const fichiers = fichiersCalendrier(sites, interventions, techniciensConnus);
  for (const [slug, f] of Object.entries(fichiers)) {
    const k = `${cle}/${slug}`;
    if (derniersIcsPublies[k] === sansDtstamp(f.ics)) continue;
    await firebaseStorageUpload(`calendriers/${cle}/${slug}.ics`, new Blob([f.ics], { type: "text/calendar; charset=utf-8" }), idToken);
    derniersIcsPublies[k] = sansDtstamp(f.ics);
  }
  return { cle, fichiers };
}
// Fenêtre « Synchroniser avec mon agenda » : liens d'abonnement par technicien.
function AbonnementCalendrierModal({ sites, interventions, techniciensConnus, user, onFermer }) {
  const [etat, setEtat] = useState({ chargement: true, erreur: "", cle: null, fichiers: null });
  const [copie, setCopie] = useState("");
  const publier = async (renouveler = false) => {
    setEtat((e) => ({ ...e, chargement: true, erreur: "" }));
    try {
      if (renouveler) { const idToken = await user.getIdToken(); await cleCalendrier(idToken, user.email, { renouveler: true }); }
      const r = await publierCalendriers(sites, interventions, techniciensConnus, user);
      setEtat({ chargement: false, erreur: "", cle: r.cle, fichiers: r.fichiers });
    } catch (e) {
      setEtat({ chargement: false, erreur: "Publication impossible (réseau, ou règle Storage « calendriers » absente).", cle: null, fichiers: null });
    }
  };
  useEffect(() => { publier(false); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const copier = async (texte, cle) => { try { await navigator.clipboard.writeText(texte); setCopie(cle); setTimeout(() => setCopie(""), 2000); } catch (e) { window.prompt("Copiez le lien :", texte); } };
  const entrees = etat.fichiers ? Object.entries(etat.fichiers).sort((a, b) => (a[0] === "tous" ? -1 : b[0] === "tous" ? 1 : a[1].nom.localeCompare(b[1].nom))) : [];
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={onFermer}>
      <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", borderRadius: 12, width: "min(600px, 100%)", maxHeight: "90vh", overflowY: "auto", padding: 16 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <b style={{ fontSize: 15 }}>Synchroniser avec mon agenda</b>
          <button onClick={onFermer} style={{ background: "none", border: "none", cursor: "pointer", color: "#5B6B7D" }}><X size={18} /></button>
        </div>
        <div style={{ fontSize: 12, color: "#5B6B7D", lineHeight: 1.5, marginBottom: 10 }}>
          Chaque technicien s'abonne à SON calendrier (une seule fois) : les interventions planifiées y apparaissent et se mettent à jour automatiquement — site, adresse avec itinéraire, contact sur site (appel / e-mail), équipements et pièces d'usure à remplacer. Sens unique : l'app alimente l'agenda.
        </div>
        {etat.chargement && <div style={{ fontSize: 13, color: "#5B6B7D", padding: 10 }}>Publication des calendriers…</div>}
        {etat.erreur && <div style={{ fontSize: 13, color: "#C0392B", padding: 10 }}>{etat.erreur}</div>}
        {entrees.map(([slug, f]) => {
          const url = urlCalendrier(etat.cle, slug);
          return (
            <div key={slug} style={{ border: "1px solid #E2E6EB", borderRadius: 10, padding: 10, marginBottom: 8 }}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>{f.nom} <span style={{ fontWeight: 400, color: "#8B96A3", fontSize: 11.5 }}>({(f.ics.match(/BEGIN:VEVENT/g) || []).length} intervention(s))</span></div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <a href={url.replace(/^https:/, "webcal:")} style={{ ...btnGhost(BRAND.blue), textDecoration: "none" }}><Clock size={13} /> S'abonner (iPhone / Mac)</a>
                <button onClick={() => copier(url, slug)} style={btnGhost()}><Copy size={13} /> {copie === slug ? "Lien copié" : "Copier le lien (Outlook, Google…)"}</button>
              </div>
            </div>
          );
        })}
        {etat.fichiers && (
          <div style={{ fontSize: 11.5, color: "#5B6B7D", lineHeight: 1.5, marginTop: 6 }}>
            <b>Outlook</b> : Calendrier → Ajouter un calendrier → « S'abonner à partir du web » / « Depuis Internet », puis coller le lien. <b>Google Agenda</b> : Autres agendas → « À partir de l'URL ».
            Délai de mise à jour : quelques minutes sur iPhone / Mac (réglable : Réglages → Calendrier → Comptes → Calendriers avec abonnement), jusqu'à plusieurs heures sur Outlook et Google.
          </div>
        )}
        <div style={{ display: "flex", justifyContent: "space-between", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
          <button onClick={() => { if (window.confirm("Générer de nouveaux liens ? Les anciens abonnements cesseront d'être mis à jour : chaque technicien devra se réabonner.")) publier(true); }} style={btnGhost("#C0392B")}><RefreshCw size={13} /> Renouveler les liens</button>
          <button onClick={onFermer} style={btnPrimary()}>Fermer</button>
        </div>
      </div>
    </div>
  );
}
function buildCalendarEvents(sites, interventions) {
  const events = [];
  sites.forEach((s) => {
    if (s.rapport && s.rapport.date) {
      events.push({ id: "site-" + s.id, dateISO: s.rapport.date, kind: "site", label: s.nom || "Site sans nom", sub: s.client, statusLabel: rankToLabel(overallRank(s)), refId: s.id, technicien: s.rapport.intervenant || "" });
    }
  });
  interventions.forEach((iv) => {
    if (iv.date) {
      events.push({ id: "iv-" + iv.id, dateISO: iv.date, kind: "intervention", label: iv.client || "Client non renseigné", sub: iv.numeroRI, statusLabel: iv.conclusion, refId: iv.id, technicien: iv.technicien || "" });
    }
  });
  return events;
}

function EventChip({ ev, onClick }) {
  const rank = RANK_OF[ev.statusLabel] ?? 0;
  const color = RANK_COLOR[rank].color;
  return (
    <div onClick={(e) => { e.stopPropagation(); onClick(); }} style={{
      display: "flex", alignItems: "center", gap: 5, padding: "2px 6px", borderRadius: 5, background: `${color}1F`,
      fontSize: 10.5, color: "#1A1F26", cursor: "pointer", overflow: "hidden", whiteSpace: "nowrap", textOverflow: "ellipsis",
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: color, flexShrink: 0 }} />
      <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>{ev.label}</span>
    </div>
  );
}

function DayDetailPanel({ dateISO, events, onOpenSite, onOpenIntervention, onCreateForDate, onCreateInterventionForDate }) {
  const d = parseIso(dateISO);
  const label = `${d.getDate()} ${MONTHS_FR[d.getMonth()]} ${d.getFullYear()}`;
  return (
    <Card style={{ marginTop: 14 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
        <SectionTitle>{label}</SectionTitle>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button onClick={() => onCreateForDate(dateISO)} style={btnGhost(BRAND.amber)}><Plus size={13} /> Préparer un rapport ce jour</button>
          <button onClick={() => onCreateInterventionForDate(dateISO)} style={btnGhost(BRAND.blue)}><ClipboardList size={13} /> Créer un compte rendu d'intervention</button>
        </div>
      </div>
      {events.length === 0 ? (
        <div style={{ textAlign: "center", padding: 18, color: "#8B96A3", fontSize: 12.5, border: "1px dashed #D8DEE5", borderRadius: 10 }}>
          Aucune intervention prévue ce jour
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {events.map((ev) => (
            <div key={ev.id} onClick={() => (ev.kind === "site" ? onOpenSite(ev.refId) : onOpenIntervention(ev.refId))}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", background: "#F7F8FA", border: "1px solid #D8DEE5", borderRadius: 10, cursor: "pointer" }}>
              {ev.kind === "site" ? <Building2 size={14} color="#5B6B7D" /> : <ClipboardList size={14} color="#5B6B7D" />}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 600, color: "#1A1F26", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{ev.label}</div>
                <div style={{ fontSize: 11, color: "#5B6B7D" }}>{ev.kind === "site" ? "Site" : "Compte rendu d'intervention"} {ev.sub ? "· " + ev.sub : ""}</div>
              </div>
              <StatusBadge label={ev.statusLabel} size="sm" />
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

function CalendarView({ sites, interventions, onOpenSite, onOpenIntervention, onCreateForDate, onCreateInterventionForDate }) {
  const [mode, setMode] = useState("month");
  const [abonnementOuvert, setAbonnementOuvert] = useState(false);
  const [ref, setRef] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState(null);
  const todayIso = todayISO();
  const allEvents = useMemo(() => buildCalendarEvents(sites, interventions), [sites, interventions]);
  const techniciensDisponibles = useMemo(() => {
    const set = new Set();
    allEvents.forEach((e) => { if (e.technicien) set.add(e.technicien); });
    return Array.from(set).sort((a, b) => a.localeCompare(b));
  }, [allEvents]);
  // Vide = tous les techniciens affichés (comportement d'origine) ; sinon, filtre à la sélection.
  const [techniciensFiltre, setTechniciensFiltre] = useState([]);
  const [filtreOuvert, setFiltreOuvert] = useState(false);
  const toggleTechnicien = (t) => setTechniciensFiltre((prev) => prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t]);
  const events = useMemo(() => {
    if (techniciensFiltre.length === 0) return allEvents;
    return allEvents.filter((e) => techniciensFiltre.includes(e.technicien));
  }, [allEvents, techniciensFiltre]);
  const byDate = useMemo(() => {
    const m = {};
    events.forEach((e) => { (m[e.dateISO] = m[e.dateISO] || []).push(e); });
    return m;
  }, [events]);

  useEffect(() => {
    if (mode === "day") setSelectedDay(isoOf(ref));
  }, [mode, ref]);

  function shift(delta) {
    setRef((prev) => {
      const d = new Date(prev);
      if (mode === "month") d.setMonth(d.getMonth() + delta);
      else if (mode === "week") d.setDate(d.getDate() + delta * 7);
      else d.setDate(d.getDate() + delta);
      return d;
    });
  }

  let headerLabel;
  if (mode === "month") headerLabel = `${MONTHS_FR[ref.getMonth()]} ${ref.getFullYear()}`;
  else if (mode === "week") {
    const start = startOfWeekMon(ref), end = addDays(start, 6);
    headerLabel = `${start.getDate()} ${MONTHS_FR[start.getMonth()]} – ${end.getDate()} ${MONTHS_FR[end.getMonth()]} ${end.getFullYear()}`;
  } else headerLabel = `${WEEKDAYS_FR[(ref.getDay() + 6) % 7]} ${ref.getDate()} ${MONTHS_FR[ref.getMonth()]} ${ref.getFullYear()}`;

  const modeBtn = (key, label) => (
    <button onClick={() => setMode(key)} style={{
      padding: "6px 13px", borderRadius: 999, border: mode === key ? "1px solid #FFC10755" : "1px solid #D8DEE5",
      background: mode === key ? "rgba(255,193,7,0.12)" : "transparent", color: mode === key ? BRAND.amber : "#5B6B7D",
      fontSize: 12, fontWeight: 600, cursor: "pointer",
    }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14, flexWrap: "wrap", gap: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <button onClick={() => shift(-1)} style={btnGhost()}><ArrowLeft size={14} /></button>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#1A1F26", minWidth: 180 }}>{headerLabel}</div>
          <button onClick={() => shift(1)} style={{ ...btnGhost(), transform: "scaleX(-1)" }}><ArrowLeft size={14} /></button>
          <button onClick={() => { setRef(new Date()); setSelectedDay(todayIso); }} style={btnGhost()}>Aujourd'hui</button>
        </div>
        <div style={{ display: "flex", gap: 6, alignItems: "center", position: "relative", flexWrap: "wrap" }}>
          {CURRENT_USER_FOR_STORAGE && <button onClick={() => setAbonnementOuvert(true)} style={btnGhost(BRAND.blue)} title="S'abonner au planning depuis Calendrier Apple, Outlook ou Google Agenda"><Clock size={14} /> Synchroniser avec mon agenda</button>}
          {abonnementOuvert && <AbonnementCalendrierModal sites={sites} interventions={interventions} techniciensConnus={[...LISTE_INTERVENANTS, ...techniciensDisponibles]} user={CURRENT_USER_FOR_STORAGE} onFermer={() => setAbonnementOuvert(false)} />}
          {techniciensDisponibles.length > 0 && (
            <>
              <button onClick={() => setFiltreOuvert((o) => !o)} style={btnGhost(techniciensFiltre.length > 0 ? BRAND.blue : undefined)}>
                <Users size={14} /> {techniciensFiltre.length === 0 ? "Tous les techniciens" : `${techniciensFiltre.length} technicien${techniciensFiltre.length > 1 ? "s" : ""}`}
              </button>
              {filtreOuvert && (
                <div style={{ position: "absolute", right: 0, top: "110%", background: "#F7F8FA", border: "1px solid #D8DEE5", borderRadius: 10, overflow: "hidden", zIndex: 50, minWidth: 220, maxHeight: 280, overflowY: "auto", boxShadow: "0 12px 30px rgba(0,0,0,0.4)" }}>
                  <div onClick={() => setTechniciensFiltre([])} style={{ padding: "9px 14px", fontSize: 12, fontWeight: 700, color: techniciensFiltre.length === 0 ? BRAND.blue : "#3E4A5C", cursor: "pointer", borderBottom: "1px solid #E2E6EB" }}>
                    Tous les techniciens
                  </div>
                  {techniciensDisponibles.map((t) => (
                    <label key={t} style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 14px", fontSize: 12, color: "#3E4A5C", cursor: "pointer", borderBottom: "1px solid #E2E6EB" }}>
                      <input type="checkbox" checked={techniciensFiltre.includes(t)} onChange={() => toggleTechnicien(t)} style={{ accentColor: BRAND.blue }} />
                      {t}
                    </label>
                  ))}
                </div>
              )}
            </>
          )}
          {modeBtn("day", "Jour")}
          {modeBtn("week", "Semaine")}
          {modeBtn("month", "Mois")}
        </div>
      </div>

      {mode === "month" && (() => {
        const firstOfMonth = new Date(ref.getFullYear(), ref.getMonth(), 1);
        const gridStart = startOfWeekMon(firstOfMonth);
        const cells = Array.from({ length: 42 }, (_, i) => addDays(gridStart, i));
        return (
          <div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6, marginBottom: 6 }}>
              {WEEKDAYS_FR.map((w) => <div key={w} style={{ textAlign: "center", fontSize: 10.5, fontWeight: 700, color: "#8B96A3", textTransform: "uppercase" }}>{w}</div>)}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6 }}>
              {cells.map((d) => {
                const iso = isoOf(d);
                const inMonth = d.getMonth() === ref.getMonth();
                const dayEvents = byDate[iso] || [];
                const isToday = iso === todayIso;
                const isSelected = iso === selectedDay;
                return (
                  <div key={iso} onClick={() => setSelectedDay(iso)} style={{
                    minHeight: 74, borderRadius: 8, padding: 6, cursor: "pointer",
                    background: isSelected ? "rgba(255,193,7,0.10)" : "#F7F8FA",
                    border: isSelected ? "1px solid #FFC10788" : isToday ? "1px solid #0A5DA8" : "1px solid #D8DEE5",
                    opacity: inMonth ? 1 : 0.4,
                  }}>
                    <div style={{ fontSize: 11, fontWeight: isToday ? 800 : 600, color: isToday ? "#FFC107" : "#3E4A5C", marginBottom: 4 }}>{d.getDate()}</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                      {dayEvents.slice(0, 2).map((ev) => <EventChip key={ev.id} ev={ev} onClick={() => (ev.kind === "site" ? onOpenSite(ev.refId) : onOpenIntervention(ev.refId))} />)}
                      {dayEvents.length > 2 && <div style={{ fontSize: 10, color: "#8B96A3" }}>+{dayEvents.length - 2}</div>}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}

      {mode === "week" && (() => {
        const start = startOfWeekMon(ref);
        const days = Array.from({ length: 7 }, (_, i) => addDays(start, i));
        return (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 8 }}>
            {days.map((d) => {
              const iso = isoOf(d);
              const dayEvents = byDate[iso] || [];
              const isToday = iso === todayIso;
              return (
                <div key={iso} onClick={() => setSelectedDay(iso)} style={{
                  minHeight: 140, borderRadius: 10, padding: 10, cursor: "pointer", background: "#F7F8FA",
                  border: iso === selectedDay ? "1px solid #FFC10788" : isToday ? "1px solid #0A5DA8" : "1px solid #D8DEE5",
                }}>
                  <div style={{ fontSize: 10.5, fontWeight: 700, color: "#8B96A3", textTransform: "uppercase" }}>{WEEKDAYS_FR[(d.getDay() + 6) % 7]}</div>
                  <div style={{ fontSize: 15, fontWeight: isToday ? 800 : 600, color: isToday ? "#FFC107" : "#1A1F26", marginBottom: 8 }}>{d.getDate()}</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    {dayEvents.map((ev) => <EventChip key={ev.id} ev={ev} onClick={() => (ev.kind === "site" ? onOpenSite(ev.refId) : onOpenIntervention(ev.refId))} />)}
                  </div>
                </div>
              );
            })}
          </div>
        );
      })()}

      {(selectedDay || mode === "day") && (
        <DayDetailPanel
          dateISO={mode === "day" ? isoOf(ref) : (selectedDay || todayIso)}
          events={byDate[mode === "day" ? isoOf(ref) : (selectedDay || todayIso)] || []}
          onOpenSite={onOpenSite}
          onOpenIntervention={onOpenIntervention}
          onCreateForDate={onCreateForDate}
          onCreateInterventionForDate={onCreateInterventionForDate}
        />
      )}
    </div>
  );
}

/* =========================================================================
   App
   ========================================================================= */
/* =========================================================================
   Export Word (.docx réel) — via la bibliothèque "docx", compatible
   Microsoft Word ET Pages sur Mac (contrairement à l'ancienne astuce HTML
   qui n'était comprise que par Word).
   ========================================================================= */
// La bibliothèque "docx" est chargée dynamiquement (pas en import statique) : l'aperçu
// d'artefact de Claude n'autorise qu'une liste fixe de bibliothèques et planterait au
// chargement si "docx" était importée en haut du fichier. Une fois l'app réellement
// déployée (Vercel, etc.), ce chargement dynamique résout normalement le vrai paquet npm.
let DOCX = null;
// Nombre décimal écrit à la française dans les documents Word : « 84.068 » → « 84,068 ». Les références (« 3022513.40 »),
// versions (« V4.02 ») et suites à plusieurs points (« 1.2.3 ») ne sont pas touchées.
function virguleDecimale(t) {
  const s = String(t);
  // Références produit gardées telles quelles (« Micrologic 5.0 », « MP 2.10 », « Ekip 1.2 »…) : ce ne sont pas des nombres décimaux.
  return s.replace(/(^|[^\w.,/])(\d{1,6})\.(\d+)(?![\w./])/g, (m, a, x, y, pos) => (/(micrologic[\s\d.,/]*|\bmp|\bekip|\bversion|\bv)\s*$/i.test(s.slice(0, pos + a.length)) ? m : `${a}${x},${y}`));
}
async function ensureDocx() {
  if (!DOCX) {
    const mod = await import("docx");
    // Police Arial écrite sur chaque texte : Pages (Mac / iPhone) ignore la police par défaut du document et affichait du Times.
    class TextRunFr extends mod.TextRun {
      constructor(o) {
        if (typeof o === "string") super({ text: virguleDecimale(o), font: "Arial" });
        else if (o && typeof o.text === "string") super({ font: "Arial", ...o, text: virguleDecimale(o.text) });
        else if (o && typeof o === "object") super({ font: "Arial", ...o });
        else super(o);
      }
    }
    DOCX = { ...mod, TextRun: TextRunFr };
  }
  return DOCX;
}

const DOCX_BLUE = "0A5DA8", DOCX_DARK = "1A1F26", DOCX_SILVER = "C0C6CE", DOCX_AMBER = "FFC107";
// Largeur standard de tous les tableaux du rapport (homogénéité visuelle) + marges internes
// des cellules (un peu plus aérées que le rendu compact précédent).
const TABLE_WIDTH = 9600;
const CELL_MARGINS = { top: 130, bottom: 130, left: 130, right: 120 };
const CELL_MARGINS_UNE_LIGNE = { top: 85, bottom: 85, left: 130, right: 120 };
const DOCX_GREEN = "0F8A5F", DOCX_ORANGE = "B5730A", DOCX_RED = "C0392B", DOCX_WHITE = "FFFFFF", DOCX_LIGHT = "F4F6F8";
// Tableaux modernisés : en-têtes bleu marine plus fins, lignes alternées très légères, états en pastilles.
const DOCX_ENTETE = "26364A", DOCX_ZEBRE = "F7F9FB";
const CELL_MARGINS_ENTETE = { top: 70, bottom: 70, left: 130, right: 120 };
// ----- Charte graphique du rapport — reprise de la présentation commerciale HT Maintenance -----
// Fond sombre #1A1F26, bleu #0A5DA8, ambre #FFC107, gris argent #C0C6CE ; barre bleue verticale devant les titres, cartes à filet de couleur,
// mot-symbole « HT MAINTENANCE » à barre bleue, bande ambre en pied de couverture. Police Calibri (présente dans Word) en capitales espacées pour les titres.
const A4_LARGEUR = 11906, A4_HAUTEUR = 16838;
// Arial : présente sur Windows, Mac, iPhone et iPad (Calibri manquait sur iPhone / Pages, remplacée par une police à empattements).
const DOCX_STYLES = { default: { document: { run: { font: "Arial", color: DOCX_DARK } } } };
// Une seule section et des marges normales pour tout le document : Pages ne gère pas des marges différentes d'une section à l'autre, ni les sauts de page
// par propriété de paragraphe, ni les hauteurs de ligne / de rangée « exactes » — on s'en tient donc aux éléments que Word, LibreOffice et Pages respectent tous.
const PAGE_CORPS = { size: { width: A4_LARGEUR, height: A4_HAUTEUR }, margin: { top: 900, bottom: 1100, left: 1153, right: 1153, header: 400, footer: 380 } }; // pied de page sur deux lignes (pagination + mention de propriété) : place suffisante aussi dans Pages
function docxTable(opts) {
  const aucune = { style: DOCX.BorderStyle.NONE, size: 0, color: "FFFFFF" };
  const fin = { style: DOCX.BorderStyle.SINGLE, size: 4, color: "E2E6EB" };
  const complet = { borders: { top: fin, bottom: fin, left: aucune, right: aucune, insideHorizontal: fin, insideVertical: aucune }, ...opts };
  const t = new DOCX.Table(complet);
  t.__opts = complet; // gardé pour pouvoir fusionner ce tableau dans un bloc insécable sans l'imbriquer
  return t;
}
const docxAucuneBordure = () => ({ style: DOCX.BorderStyle.NONE, size: 0, color: "FFFFFF" });
const docxToutesAucune = () => { const a = docxAucuneBordure(); return { top: a, bottom: a, left: a, right: a }; };
const docxMiniParagraphe = () => new DOCX.Paragraph({ spacing: { before: 0, after: 0 }, children: [new DOCX.TextRun({ text: "", size: 4 })] });
// Carte : fond clair ou blanc, filet de couleur en haut, petit libellé en capitales puis valeur en gras.
function docxCarte({ label, valeur, couleur, taille = 30, sousTexte, fond = DOCX_WHITE, filet = "haut", compact = false }, largeur) {
  const a = docxAucuneBordure();
  const trait = { style: DOCX.BorderStyle.SINGLE, size: filet === "gauche" ? 48 : 36, color: couleur };
  return new DOCX.TableCell({
    width: { size: largeur, type: DOCX.WidthType.DXA }, shading: { type: DOCX.ShadingType.CLEAR, fill: fond },
    margins: { top: 190, bottom: 210, left: compact ? 170 : filet === "gauche" ? 300 : 260, right: compact ? 100 : 200 }, verticalAlign: DOCX.VerticalAlign.CENTER,
    borders: filet === "gauche" ? { top: a, bottom: a, left: trait, right: a } : { top: trait, bottom: a, left: a, right: a },
    children: [
      new DOCX.Paragraph({ spacing: { after: 50 }, children: [new DOCX.TextRun({ text: String(label || "").toUpperCase(), bold: true, size: compact ? 14 : 15, color: "66717E", characterSpacing: compact ? 0 : 30 })] }),
      new DOCX.Paragraph({ spacing: { after: 0 }, children: [new DOCX.TextRun({ text: String(valeur === undefined || valeur === null || valeur === "" ? "—" : valeur), bold: true, size: taille, color: DOCX_DARK })] }),
      ...(sousTexte ? [new DOCX.Paragraph({ spacing: { before: 50, after: 0 }, children: [new DOCX.TextRun({ text: sousTexte, size: 17, color: "5A6573" })] })] : []),
    ],
  });
}
function docxRangeeCartes(cartes, largeurTotale, ecart = 220) {
  const n = cartes.length, lc = Math.floor((largeurTotale - ecart * (n - 1)) / n);
  const cellules = [], colonnes = [];
  cartes.forEach((c, i) => {
    if (i) { cellules.push(new DOCX.TableCell({ width: { size: ecart, type: DOCX.WidthType.DXA }, borders: docxToutesAucune(), children: [docxMiniParagraphe()] })); colonnes.push(ecart); }
    cellules.push(docxCarte(c, lc)); colonnes.push(lc);
  });
  return docxTable({ width: { size: largeurTotale, type: DOCX.WidthType.DXA }, columnWidths: colonnes, borders: { ...docxToutesAucune(), insideHorizontal: docxAucuneBordure(), insideVertical: docxAucuneBordure() }, rows: [new DOCX.TableRow({ cantSplit: true, children: cellules })] });
}

function docxEtatColor(label) {
  const rank = RANK_OF[label] ?? 0;
  if (rank === 2) return DOCX_RED;
  if (rank === 1) return DOCX_ORANGE;
  if (rank === -1) return "7A8794";
  return DOCX_GREEN;
}
// Bloc d'une seule ligne de tableau, sans bordure ni marge : ce qu'il contient (titre + image, par
// exemple) ne peut JAMAIS être séparé par un saut de page, quel que soit le logiciel — une ligne de
// tableau ne se coupe pas entre deux pages. Le réglage « garder avec le suivant » seul ne suffit pas :
// Word et LibreOffice le respectent, mais Pages l'ignore.
function docxBlocInsecable(enfants) {
  const aucune = { style: DOCX.BorderStyle.NONE, size: 0, color: "FFFFFF" };
  const bordures = { top: aucune, bottom: aucune, left: aucune, right: aucune };
  // Un tableau dans un tableau est converti en texte par Pages (iPhone / Mac) : quand le bloc contient
  // un tableau, les paragraphes avant / après deviennent des lignes de CE tableau (pas d'imbrication).
  const tableaux = (enfants || []).filter((e) => e instanceof DOCX.Table);
  if (tableaux.length === 1 && tableaux[0].__opts && Array.isArray(tableaux[0].__opts.columnWidths) && Array.isArray(tableaux[0].__opts.rows)) {
    const t = tableaux[0], o = t.__opts, idx = enfants.indexOf(t);
    const nbCol = o.columnWidths.length;
    const largeur = o.columnWidths.reduce((x, y) => x + y, 0);
    const avant = enfants.slice(0, idx).filter(Boolean), apres = enfants.slice(idx + 1).filter(Boolean);
    const ligne = (paras) => new DOCX.TableRow({ cantSplit: true, children: [new DOCX.TableCell({
      columnSpan: nbCol, width: { size: largeur, type: DOCX.WidthType.DXA }, margins: { top: 0, bottom: 0, left: 0, right: 0 },
      borders: { top: aucune, left: aucune, right: aucune, bottom: aucune },
      children: paras,
    })] });
    const bTable = o.borders || {};
    const rows = [
      ...(avant.length ? [ligne(avant)] : []),
      ...o.rows,
      ...(apres.length ? [ligne(apres)] : []),
    ];
    return new DOCX.Table({ ...o, borders: { ...bTable, top: avant.length ? aucune : bTable.top, bottom: apres.length ? aucune : bTable.bottom }, rows });
  }
  return docxTable({
    width: { size: TABLE_WIDTH, type: DOCX.WidthType.DXA }, columnWidths: [TABLE_WIDTH],
    borders: { ...bordures, insideHorizontal: aucune, insideVertical: aucune },
    rows: [new DOCX.TableRow({ cantSplit: true, children: [new DOCX.TableCell({
      width: { size: TABLE_WIDTH, type: DOCX.WidthType.DXA }, margins: { top: 0, bottom: 0, left: 0, right: 0 }, borders: bordures,
      children: enfants,
    })] })],
  });
}
function docxHeading(text, avant = 680, apres = 200) {
  return new DOCX.Paragraph({
    spacing: { before: avant, after: apres },
    keepNext: true,
    indent: { left: 170 },
    border: { left: { color: DOCX_BLUE, space: 9, style: DOCX.BorderStyle.SINGLE, size: 36 } },
    children: [new DOCX.TextRun({ text: (text || "").toUpperCase(), bold: true, color: DOCX_DARK, size: 24, characterSpacing: 24 })],
  });
}
// Petite note en italique indiquant la norme/référence appliquée pour un contrôle donné — pour
// tracer la méthode utilisée sans alourdir le tableau de mesures lui-même.
// Rendu Word des remarques : sous-titres en couleur, puces avec retrait, texte libre en paragraphes.
function docxSousTitreRemarques(texte) {
  return new DOCX.Paragraph({ spacing: { before: 120, after: 70 }, keepNext: true, children: [new DOCX.TextRun({ text: texte, bold: true, size: 18, color: DOCX_BLUE })] });
}
function docxPuces(items, size = 18, espace = 50) {
  return items.map((t) => new DOCX.Paragraph({ spacing: { after: espace }, indent: { left: 260, hanging: 220 }, children: [new DOCX.TextRun({ text: "•  " + t, size })] }));
}
// Carte « Constats | Préconisations » : deux colonnes côte à côte, liseré et teinte de l'état de l'équipement.
// Une seule rangée de tableau (insécable si le texte est raisonnable) : la carte ne se coupe pas entre deux pages, Pages compris.
//  - titre (optionnel) : nom de l'équipement, cliquable vers sa fiche si `lien` est fourni ; pastille d'état à droite.
//  - autres : lignes libres (texte non structuré) affichées au-dessus des constats.
function docxCarteRemarques({ titre = "", lien = "", etat = "", constats = [], preconisations = [], autres = [] }) {
  const rang = RANK_OF[etat] ?? 0;
  const teinte = teinteSyntheseRang(rang);
  const a = docxAucuneBordure();
  const W = [4800, 4800];
  const fond = { type: DOCX.ShadingType.CLEAR, fill: "FAFBFC" };
  const etiquette = (t, couleur) => new DOCX.Paragraph({ keepNext: true, spacing: { before: 60, after: 90 }, border: { bottom: { style: DOCX.BorderStyle.SINGLE, size: 6, color: couleur, space: 3 } },
    children: [new DOCX.TextRun({ text: t, bold: true, size: 16, color: couleur, characterSpacing: 30 })] });
  const puce = (t, symbole, couleurSymbole) => new DOCX.Paragraph({ spacing: { before: 0, after: 80, line: 288 }, indent: { left: 300, hanging: 300 },
    children: [new DOCX.TextRun({ text: symbole, bold: true, size: 20, color: couleurSymbole }), new DOCX.TextRun({ text: "\u00A0\u00A0" + finPhrase(t), size: 20, color: DOCX_DARK })] });
  const vide = (t) => new DOCX.Paragraph({ spacing: { after: 40 }, children: [new DOCX.TextRun({ text: t, size: 20, italics: true, color: "66717E" })] });
  const ligneTitre = titre ? [new DOCX.Paragraph({ keepNext: true, spacing: { before: 0, after: 60 }, children: [
    lien ? new DOCX.InternalHyperlink({ anchor: lien, children: [new DOCX.TextRun({ text: titre, bold: true, size: 21, color: DOCX_DARK })] }) : new DOCX.TextRun({ text: titre, bold: true, size: 21, color: DOCX_DARK }),
  ] })] : [];
  const lignePastille = titre ? [new DOCX.Paragraph({ keepNext: true, alignment: DOCX.AlignmentType.RIGHT, spacing: { before: 0, after: 60 }, children: [
    new DOCX.TextRun({ text: "\u200B", size: 21 }), // même hauteur de ligne que le nom de l'équipement : « Constats » et « Préconisations » alignés
    new DOCX.TextRun({ text: "\u00A0\u00A0●\u00A0", bold: true, size: 15, color: teinte.barre, shading: { type: DOCX.ShadingType.CLEAR, fill: teinte.fond, color: "auto" } }),
    new DOCX.TextRun({ text: (rang < 0 ? String(etat || "").toUpperCase() : teinte.etiquette) + "\u00A0\u00A0", bold: true, size: 15, color: teinte.texte, characterSpacing: 10, shading: { type: DOCX.ShadingType.CLEAR, fill: teinte.fond, color: "auto" } }),
  ] })] : [];
  const libres = autres.map((t) => new DOCX.Paragraph({ spacing: { after: 80, line: 288 }, children: [new DOCX.TextRun({ text: t, size: 20, color: DOCX_DARK })] }));
  const gauche = [...ligneTitre, ...libres, etiquette("CONSTATS", "4A5563"), ...(constats.length ? constats.map((t) => puce(t, "•", "66717E")) : [vide("Aucune remarque particulière.")])];
  const pucePreco = (t) => {
    const m = String(t).match(/^(.*?)\s*—\s*Prioritaire\.?$/i);
    if (!m) return puce(t, "→", teinte.barre);
    return new DOCX.Paragraph({ spacing: { before: 0, after: 80, line: 288 }, indent: { left: 300, hanging: 300 }, children: [
      new DOCX.TextRun({ text: "→", bold: true, size: 20, color: teinte.barre }), new DOCX.TextRun({ text: "\u00A0\u00A0" + finPhrase(m[1]) + " ", size: 20, color: DOCX_DARK }),
      new DOCX.TextRun({ text: "PRIORITAIRE", bold: true, size: 15, color: "C0392B", characterSpacing: 10 })] });
  };
  const droite = [...lignePastille, etiquette("NOS PRÉCONISATIONS", teinte.texte), ...(preconisations.length ? preconisations.map(pucePreco) : [vide("Aucune action nécessaire.")])];
  const longueur = [...autres, ...constats, ...preconisations].join(" ").length;
  return docxTable({
    width: { size: TABLE_WIDTH, type: DOCX.WidthType.DXA }, columnWidths: W, borders: { ...docxToutesAucune(), insideHorizontal: a, insideVertical: a },
    rows: [new DOCX.TableRow({ cantSplit: longueur < 900, children: [
      new DOCX.TableCell({ width: { size: W[0], type: DOCX.WidthType.DXA }, shading: fond, margins: { top: 170, bottom: 120, left: 260, right: 200 },
        borders: { top: a, bottom: a, right: { style: DOCX.BorderStyle.SINGLE, size: 4, color: "E2E6EB" }, left: { style: DOCX.BorderStyle.SINGLE, size: 48, color: teinte.barre } }, children: gauche }),
      new DOCX.TableCell({ width: { size: W[1], type: DOCX.WidthType.DXA }, shading: fond, margins: { top: 170, bottom: 120, left: 240, right: 220 }, borders: { top: a, bottom: a, left: a, right: a }, children: droite }),
    ] })],
  });
}
