  const texte = (t, x, yy, couleur = "#5B6B7D", police = "10px", align = "center") => { ctx.save(); ctx.font = `${police} ${SCHEMA_POLICE}`; ctx.fillStyle = couleur; ctx.textAlign = align; ctx.textBaseline = "middle"; ctx.fillText(t, x, yy); ctx.restore(); };
