    libelleSousRepere(ctx, `Utilisation ${regime("utilisation")}${deuxN && idc.voie2N ? ` — ${idc.voie2N}` : ""}`, xSortie, yFleche + GAP_LIGNE + 18);
    yBasDessin = Math.max(yBasDessin, yFleche + GAP_LIGNE + 48);

