  const [etudesLoaded, setEtudesLoaded] = useState(false);
  const etudesSaveTimer = useRef(null), lastSyncedEtudes = useRef(null), etudesWriteInFlight = useRef(false);
  const setEtudesCourbes = (f, o = {}) => { if (o.suppression) suppressionEtudeVolontaire.current = true; editVersionEtudes.current++; setEtudesCourbesBrut(f); };
  const contactsRefForPoll = useRef([]);
  const aDejaChargeDesContacts = useRef(false);
